        'n_connections' => 'കണക്ഷനുകൾ',
        'd_goal' => 'പൂർത്തിയായാൽ എങ്ങനെയിരിക്കും എന്ന് പറയുന്ന ഒരു വാക്യം. പ്രോജക്റ്റിലെ മറ്റെല്ലാം അതിലേക്ക് എത്താൻ വേണ്ടിയാണ്.',
        'd_case' => 'പ്രോജക്റ്റ് ചെയ്യുന്നത് എന്തുകൊണ്ട് മൂല്യവത്താണ്: നേട്ടങ്ങൾ, ചെലവുകൾ, അപകടസാധ്യതകൾ. ആദ്യ ഗേറ്റിൽ ബോർഡ് ഇതിനെ ആശ്രയിച്ച് തീരുമാനിക്കുന്നു.',
        'd_benefits' => 'പ്രോജക്റ്റ് എന്ത് മെച്ചപ്പെടുത്തണം, തുടങ്ങിയ നിലയിൽ നിന്ന് ലക്ഷ്യത്തിലേക്ക് അളക്കുന്നു - അടച്ചതിന് ശേഷവും അവലോകനം ചെയ്യുന്നു, കാരണം മിക്ക നേട്ടങ്ങളും അപ്പോഴാണ് വരുന്നത്.',
        'd_scope' => 'എത്തിച്ചുനൽകേണ്ട കാര്യങ്ങൾ, ഓരോന്നും Must, Should, Could അല്ലെങ്കിൽ Won\'t. ചില കാര്യങ്ങൾക്ക് മര്യാദയോടെ ഇല്ല എന്ന് പറയാനുള്ള വഴിയാണിത്.',
        'd_milestones' => 'പ്രോജക്റ്റ് വാഗ്ദാനം ചെയ്ത തീയതികൾ. ഒന്ന് തെറ്റിയാൽ ആരോഗ്യനില ആംബർ ആകുകയും പ്രോജക്റ്റ് മാനേജരെ അറിയിക്കുകയും ചെയ്യും.',
        'd_stages' => 'ജോലി എങ്ങനെ മുറിക്കുന്നു: ഫേസുകൾ (Simple), അവസാനം ഗേറ്റുള്ള ഘട്ടങ്ങൾ (Staged) അല്ലെങ്കിൽ രണ്ടാഴ്ചത്തെ സ്പ്രിന്റുകൾ (Agile). ഒരേ കാര്യം, വ്യത്യസ്ത കാഴ്ചപ്പാട്.',
        'd_tasks' => 'യഥാർത്ഥ ജോലി - സാധാരണ FreeITSM ടാസ്കുകൾ, അതിനാൽ അവ Tasks ബോർഡിലും ആളുകളുടെ ലിസ്റ്റുകളിലും കാണിക്കും.',
        'd_deps' => 'ആ ടാസ്ക് തീരുന്നതുവരെ ഈ ടാസ്ക് തുടങ്ങാൻ കഴിയില്ല. ഇവ ടൈംലൈനിന് അമ്പടയാളങ്ങൾ നൽകുകയും ക്രിട്ടിക്കൽ പാത്ത് കണക്കാക്കുകയും ചെയ്യുന്നു.',
        'd_timeline' => 'ഗാന്റ് ചാർട്ട്: ഘട്ടങ്ങൾ, ടാസ്കുകൾ, നാഴികക്കല്ലുകൾ ഒരു കലണ്ടറിൽ, ക്രിട്ടിക്കൽ പാത്തും പരസ്പരം ഏറ്റുമുട്ടുന്ന തീയതികളും സഹിതം.',
        'd_capacity' => 'ഓരോ ടാസ്കിനും കണക്കാക്കിയ മണിക്കൂറുകൾ അത് ചെയ്യുന്ന ആളുകൾക്കിടയിൽ വിതരണം ചെയ്യുന്നു, അതിനാൽ പ്രശ്നമാകുന്നതിന് മുമ്പ് ആർക്കാണ് അമിത ഭാരമെന്ന് കാണാം.',
        'd_people' => 'പ്രോജക്റ്റിൽ ആരൊക്കെയുണ്ട് - അനലിസ്റ്റുകൾ, മുഴുവൻ ടീമുകൾ, People മൊഡ്യൂളിലെ ആളുകൾ - ഓരോരുത്തരുടെയും റോളും.',
        'd_raci' => 'ഓരോ ഡെലിവറബിളിനും: ആര് ചെയ്യുന്നു, ആര് ഉത്തരവാദിയാണ്, ആരോട് ചോദിക്കുന്നു, ആരെ അറിയിക്കുന്നു.',
        'd_stakeholders' => 'താൽപര്യമുള്ള എല്ലാവരും, അധികാരവും താൽപര്യവും അനുസരിച്ച് സ്ഥാപിച്ചത്, അവർ എവിടെ നിൽക്കുന്നു എന്നും അവരെ എങ്ങനെ അറിയിക്കുന്നു എന്നും സഹിതം.',
        'd_raid' => 'അപകടസാധ്യതകൾ, അനുമാനങ്ങൾ, പ്രശ്നങ്ങൾ, ആശ്രിതത്വങ്ങൾ, തീരുമാനങ്ങൾ, പാഠങ്ങൾ, എന്ത് തെറ്റാം എന്നതിന്റെ ഹീറ്റ് മാപ്പ് സഹിതം.',
        'd_gates' => 'ഒരു ഘട്ടത്തിന്റെ അവസാനം ആരെങ്കിലും പോകുക, വ്യവസ്ഥകളോടെ പോകുക, അല്ലെങ്കിൽ നിർത്തുക എന്ന് പറയുന്നു. ആദ്യം എന്തെല്ലാം ശരിയായിരിക്കണം എന്ന് ഒരു ചെക്ക്‌ലിസ്റ്റ് പറയുന്നു.',
        'd_tolerances' => 'ബോർഡിലേക്ക് തിരികെ പോകേണ്ടിവരുന്നതിന് മുമ്പ് പ്രോജക്റ്റിന് എത്രത്തോളം വ്യതിചലിക്കാം - വൈകുന്ന ദിവസങ്ങൾ, റിസ്ക് സ്കോർ, ബജറ്റിന് മുകളിലുള്ള %.',
        'd_health' => 'പച്ച, ആംബർ അല്ലെങ്കിൽ ചുവപ്പ്, നിങ്ങൾ നോക്കുമ്പോഴെല്ലാം പ്ലാനിൽ നിന്ന് കണക്കാക്കുന്നു: കാലാവധി കഴിഞ്ഞ ജോലി, തെറ്റിയ നാഴികക്കല്ലുകൾ, ടോളറൻസുകൾ, ലക്ഷ്യ തീയതി.',
        'd_budget' => 'ആസൂത്രണം ചെയ്തതും ചെലവഴിച്ചതും, വരി വരിയായി, തീയതികളോടെ - അതിനാൽ കാലക്രമേണയുള്ള പണവും അവസാനം വരെയുള്ള പ്രവചനവും കാണാം.',
        'd_earned' => 'ആസൂത്രണം ചെയ്തത്, ചെയ്ത ജോലിയുടെ മൂല്യം, അതിന്റെ ചെലവ് എന്നിവ താരതമ്യം ചെയ്യുന്നു: ചെയ്ത ജോലിക്ക് ബജറ്റിനേക്കാൾ കൂടുതലാണോ, പിന്നിലാണോ?',
        'd_change' => 'അംഗീകരിച്ച പ്ലാനിന്റെ ബേസ്‌ലൈനുകളും, പ്ലാൻ നീങ്ങുന്നതിന് മുമ്പ് അംഗീകരിക്കുകയോ നിരസിക്കുകയോ ചെയ്യുന്ന മാറ്റ അഭ്യർത്ഥനകളും.',
        'd_reports' => 'ഹൈലൈറ്റ്, എക്സെപ്ഷൻ, ചെക്ക്പോയിന്റ്, ക്ലോഷർ റിപ്പോർട്ടുകൾ - നിങ്ങൾ എഴുതിയതോ പ്രോജക്റ്റിന്റെ സ്വന്തം ഡാറ്റയിൽ നിന്ന് AI തയ്യാറാക്കിയതോ, അംഗീകരിച്ച്, ഇമെയിൽ ചെയ്യുന്നു.',
        'd_alerts' => 'ആരോഗ്യനില മാറുമ്പോഴോ, നാഴികക്കല്ല് അടുക്കുമ്പോഴോ, അനുമതി ഒരുപാട് കാത്തിരിക്കുമ്പോഴോ, ടാസ്കുകളുടെ കാലാവധി കഴിയുമ്പോഴോ ബെൽ ശരിയായ വ്യക്തിയെ അറിയിക്കുന്നു.',
        'd_portfolio' => 'എല്ലാ പ്രോജക്റ്റുകളും ഒരേസമയം: കാർഡുകൾ, ഒരു റോഡ്മാപ്പ്, പ്രോജക്റ്റുകൾക്കിടയിലുള്ള ചാർട്ടുകൾ, മുൻഗണനയോ തീയതിയോ അനുസരിച്ച് ക്രമീകരിച്ചത്.',
        'd_connections' => 'പ്രോജക്റ്റ് സ്പർശിക്കുന്ന മാറ്റങ്ങൾ, ടിക്കറ്റുകൾ, പ്രശ്നങ്ങൾ, ഉപകരണങ്ങൾ, കരാറുകൾ, CI-കൾ, ലേഖനങ്ങൾ - ഇരുവശത്തേക്കും ലിങ്ക് ചെയ്തത്.',
        'w_goal' => 'പ്രോജക്റ്റിന്റെ ഫോമും അതിന്റെ ബാനറും',
