        'w_alerts' => 'ബെൽ; ഓർമ്മപ്പെടുത്തലുകൾക്ക് Projects - Settings',
        'w_portfolio' => 'Projects ഹോം - Cards, Roadmap, Charts',
        'w_connections' => 'Connections ടാബ്, ഓരോ രേഖയുടെയും സ്വന്തം പേജ്',
        's1_title' => 'ഒരു ലക്ഷ്യത്തോടെ തുടങ്ങുന്നു',
        's1_text' => 'ഒരു ഓഫീസ് മാറ്റം: "അടുത്ത പാദത്തിന്റെ അവസാനത്തോടെ 40 ജീവനക്കാരും Bradford-ൽ നിന്ന് ജോലി ചെയ്യുന്നു." ബോർഡിന്റെ അനുമതി വേണമെങ്കിൽ, ഇത് എന്തുകൊണ്ട് മൂല്യവത്താണെന്ന് ബിസിനസ് കേസ് പറയുന്നു - അത് വാഗ്ദാനം ചെയ്യുന്ന നേട്ടങ്ങളാണ് അവസാനം നിങ്ങൾ അളക്കുന്നത്.',
        's2_title' => 'കഷണങ്ങളായി മുറിക്കുക',
        's2_text' => 'നാല് ഘട്ടങ്ങൾ: സർവേയും രൂപകൽപ്പനയും, നെറ്റ്‌വർക്ക് നിർമ്മിക്കൽ, മാറ്റ വാരാന്ത്യം, ഒത്തുചേരൽ. നിങ്ങൾ വാഗ്ദാനം ചെയ്ത തീയതികളെ നാഴികക്കല്ലുകൾ അടയാളപ്പെടുത്തുന്നു - നെറ്റ്‌വർക്ക് ലൈവ്, മാറ്റ ദിനം.',
        's3_title' => 'ജോലി ആസൂത്രണം ചെയ്യുക',
        's3_text' => 'ഓരോ ഘട്ടത്തിലും ടാസ്കുകൾ ചേർക്കുന്നു. ചിലത് മറ്റുള്ളവയ്ക്കായി കാത്തിരിക്കുന്നു - കേബിളിംഗിന് മുമ്പ് സ്വിച്ചുകൾ ഇടാൻ കഴിയില്ല - ആ ആശ്രിതത്വങ്ങൾ ടൈംലൈനിന്റെ അമ്പടയാളങ്ങൾ വരയ്ക്കുകയും ക്രിട്ടിക്കൽ പാത്ത് കണ്ടെത്തുകയും ചെയ്യുന്നു.',
        's4_title' => 'ആര് എന്ത് ചെയ്യുന്നു',
        's4_text' => 'ആളുകളെ ചേർക്കുക, അവർക്ക് റോളുകൾ നൽകുക, ടാസ്കുകൾ കണക്കാക്കുക, അങ്ങനെ ആർക്കാണ് ഭാരം കൂടുതലെന്ന് Capacity കാണിക്കും. വലിയ പ്രോജക്റ്റിൽ, ഓരോ ഡെലിവറബിളിനും ആരാണ് ഉത്തരവാദിയെന്ന് RACI പറയുന്നു, ആരെ സന്തോഷിപ്പിക്കണമെന്ന് സ്റ്റേക്ക്ഹോൾഡർ മാപ്പ് പറയുന്നു.',
        's5_title' => 'എന്തെല്ലാം ഉൾപ്പെടുമെന്ന് സമ്മതിക്കുക',
        's5_text' => 'എന്ത് എത്തിച്ചുനൽകും എന്ന് സ്കോപ്പ് പട്ടികപ്പെടുത്തുന്നു: പാച്ച് ചെയ്ത ഓരോ ഡെസ്കും Must ആണ്; റിസപ്ഷനിലെ ബോർഡ് Could ആണ്. ഇത് നേരത്തെ തുറന്നു പറയുന്നത് പിന്നീടുള്ള തർക്കങ്ങൾ ഒഴിവാക്കുന്നു.',
        's6_title' => 'എന്ത് തെറ്റാമെന്ന് ശ്രദ്ധിക്കുക',
        's6_text' => 'സ്വിച്ചുകൾ വൈകി എത്തുമെന്ന അപകടസാധ്യതയും ഇന്റർനെറ്റ് ലൈൻ വൈകിയ പ്രശ്നവും RAID ലോഗ് സൂക്ഷിക്കുന്നു. എത്രത്തോളം മോശമായാൽ അധികമാകുമെന്ന് ടോളറൻസുകൾ പറയുന്നു - പ്ലാൻ അങ്ങനെ പറയുമ്പോൾ ആരോഗ്യനില സ്വയം ആംബർ അല്ലെങ്കിൽ ചുവപ്പ് ആകുന്നു.',
        's7_title' => 'പണത്തെ പിന്തുടരുക',
        's7_text' => 'തീയതികളുള്ള ബജറ്റ് വരികൾ കാലക്രമേണയുള്ള ചെലവും ഒരു പ്രവചനവും കാണിക്കുന്നു. യഥാർത്ഥത്തിൽ ചെയ്ത ജോലിയുമായി എൺഡ് വാല്യൂ അതിനെ താരതമ്യം ചെയ്യുന്നു.',
        's8_title' => 'ഗേറ്റിൽ തീരുമാനിക്കുക',
        's8_text' => 'മാറ്റ വാരാന്ത്യത്തിന് മുമ്പ്, ഗേറ്റിന്റെ ചെക്ക്‌ലിസ്റ്റ് പൂർത്തിയായിരിക്കണം - ഉപയോക്തൃ പരിശോധന അംഗീകരിച്ചു, ബാക്ക്ഔട്ട് പ്ലാൻ ചേർത്തു - അതിന് ശേഷം ആരെങ്കിലും പോകുക എന്ന് പറയുന്നു.',
        's9_title' => 'പ്ലാൻ മാറ്റേണ്ടിവരുമ്പോൾ',
        's9_text' => 'രണ്ട് മീറ്റിംഗ് റൂമുകളിൽ കൂടി സ്ക്രീനുകൾ വേണമെന്ന് ആരോ ആവശ്യപ്പെടുന്നു. ദിവസത്തിലും പണത്തിലും ഇതിന് എത്ര ചെലവാകുമെന്ന് ഒരു മാറ്റ അഭ്യർത്ഥന പറയുന്നു; അനുമതി നൽകുമ്പോൾ പുതിയ ബേസ്‌ലൈൻ എടുക്കുന്നു, അതിനാൽ പ്ലാൻ എത്ര നീങ്ങിയെന്ന് എപ്പോഴും കാണാം.',
        's10_title' => 'ആളുകളെ അറിയിക്കുക',
        's10_text' => 'ഓരോ മാസവും ഒരു ഹൈലൈറ്റ് റിപ്പോർട്ട് - വേണമെങ്കിൽ AI തയ്യാറാക്കിയത്, നിങ്ങൾ അംഗീകരിച്ചത്, സ്റ്റേക്ക്ഹോൾഡർമാർക്ക് ഇമെയിൽ ചെയ്തത്. കാര്യങ്ങൾ വൈകിക്കുന്നവരെ ബെൽ ഓർമ്മിപ്പിക്കുന്നു, പോർട്ട്ഫോളിയോ എല്ലാ പ്രോജക്റ്റുകളും അടുത്തടുത്ത് കാണിക്കുന്നു.',
        's11_title' => 'FreeITSM-ന്റെ ബാക്കി ഭാഗവുമായി ചേർക്കുക',
        's11_text' => 'പുതിയ സ്വിച്ചുകൾക്കുള്ള മാറ്റം, മാറ്റം മൂലമുണ്ടാകുന്ന ടിക്കറ്റുകൾ, കേബിളിംഗ് കമ്പനിയുമായുള്ള കരാർ എന്നിവ ലിങ്ക് ചെയ്യുക. ആ ഓരോ രേഖയും പ്രോജക്റ്റിനെ അതിന്റെ ഭാഗത്ത് നിന്നും കാണിക്കുന്നു.',
        's12_title' => 'പൂർത്തിയാക്കുക - ഇത് മൂല്യവത്തായിരുന്നോ എന്ന് പരിശോധിക്കുക',
        's12_text' => 'ഒരു ക്ലോഷർ റിപ്പോർട്ട് ഉപയോഗിച്ച് പ്രോജക്റ്റ് അടയ്ക്കുക. നേട്ടങ്ങൾ അളക്കുന്നത് തുടരുക: മാസങ്ങൾക്ക് ശേഷം, നെറ്റ്‌വർക്ക് ടിക്കറ്റുകൾ ശരിക്കും കുറഞ്ഞോ? അതാണ് യഥാർത്ഥ പരീക്ഷണം.',
    ],
    'toolbox' => [
        'title' => 'ടൂൾബോക്സ്',
