        'add' => 'ചേർക്കുക',
        'added' => '{tool} ചേർത്തു',
        'suggested' => 'നിർദ്ദേശിച്ചത്',
        'when_people' => 'ഒന്നിലധികം പേർ ഇതിൽ ജോലി ചെയ്യുമ്പോൾ.',
        'when_scope' => 'എന്ത് എത്തിച്ചുനൽകും, എന്ത് ഇല്ല എന്ന് സമ്മതിക്കേണ്ടിവരുമ്പോൾ.',
        'when_raci' => 'പലർ ജോലി പങ്കിടുകയും ആര് തീരുമാനിക്കുമെന്ന് വ്യക്തമല്ലാതിരിക്കുകയും ചെയ്യുമ്പോൾ.',
        'when_raid' => 'കാര്യങ്ങൾ തെറ്റാൻ സാധ്യതയുള്ളപ്പോൾ - അല്ലെങ്കിൽ ഇതിനകം തെറ്റിയപ്പോൾ.',
        'when_gates' => 'അടുത്ത ഘട്ടത്തിന് മുമ്പ് ആരെങ്കിലും പോകുക അല്ലെങ്കിൽ നിർത്തുക എന്ന് പറയേണ്ടപ്പോൾ.',
        'when_budget' => 'കണക്ക് ബോധിപ്പിക്കേണ്ട പണം പ്രോജക്റ്റ് ചെലവഴിക്കുമ്പോൾ.',
        'when_control' => 'പ്ലാൻ അംഗീകരിക്കുകയും അതിലെ മാറ്റങ്ങൾക്ക് അനുമതി വേണ്ടിവരികയും ചെയ്യുമ്പോൾ.',
        'when_benefits' => 'എന്ത് മെച്ചപ്പെടുത്തും എന്നതിനെ അടിസ്ഥാനമാക്കിയാണ് പ്രോജക്റ്റ് ന്യായീകരിച്ചതെങ്കിൽ.',
        'why_people' => '{count} പേർക്ക് ഇതിൽ ടാസ്കുകളുണ്ട് - പ്രോജക്റ്റിൽ ആരൊക്കെയുണ്ടെന്നും അവരുടെ റോളുകളും പട്ടികപ്പെടുത്തുക.',
        'why_scope' => '{count} ടാസ്കുകൾ ഉള്ളതിനാൽ, യഥാർത്ഥത്തിൽ എന്താണ് എത്തിക്കുന്നതെന്ന് ഒരു സ്കോപ്പ് ലിസ്റ്റ് ശ്രദ്ധിക്കുന്നു.',
        'why_raci' => 'ഇതിൽ {count} പേർ - ആര് എന്ത് ചെയ്യുന്നുവെന്ന് RACI പറയുന്നു.',
        'why_raid' => '{count} ടാസ്ക്(കൾ) കാലാവധി കഴിഞ്ഞു - അതിനു പിന്നിലെ പ്രശ്നങ്ങളും അപകടസാധ്യതകളും RAID ലോഗ് ട്രാക്ക് ചെയ്യുന്നു.',
