        'ev_note_hours' => 'ബജറ്റിനെ ചെയ്തുതീർത്ത ജോലിയുടെ അനുപാതം കൊണ്ട് ഗുണിച്ചതാണ് എൺഡ് വാല്യു; ഈ അനുപാതം കണക്കാക്കുന്നത് എസ്റ്റിമേറ്റ് ചെയ്ത മണിക്കൂറുകൾ കൊണ്ടാണ്. പ്ലാൻഡ് വാല്യു ബജറ്റ് വരികളുടെ ആസൂത്രിത തീയതികളിൽ നിന്നും, യഥാർത്ഥ ചെലവ് ചെലവാക്കിയതിൽ നിന്നും വരുന്നു.',
