        'ai_intro' => 'ഇവിടെ ഒരു പ്രൊവൈഡർ സജ്ജമാക്കിയാൽ, പ്രോജക്റ്റിന്റെ Overview ഒരു ചെറിയ ബ്രീഫിംഗ് നൽകും - ഈ ആഴ്ച ശ്രദ്ധ വേണ്ടത് എന്തിനെല്ലാം എന്ന്. Reports ടാബ് ഹൈലൈറ്റ്, എക്സെപ്ഷൻ, ചെക്ക്‌പോയിന്റ്, ക്ലോഷർ റിപ്പോർട്ടുകളുടെ ഡ്രാഫ്റ്റ് തയ്യാറാക്കും. AI നിർദ്ദേശിക്കുക മാത്രമേ ചെയ്യൂ: പ്രോജക്റ്റ് മാനേജർ അനുമതി നൽകുന്നതുവരെ റിപ്പോർട്ട് ഡ്രാഫ്റ്റ് മാത്രമാണ്.',
        'ai_privacy' => 'അയയ്ക്കുന്നത്: പ്രോജക്റ്റിന്റെ പേര്, ലക്ഷ്യം, സംഗ്രഹം, ബിസിനസ് കേസ്, തീയതികൾ, ഹെൽത്തും ടോളറൻസുകളും, ഘട്ടങ്ങളും ഗേറ്റ് തീരുമാനങ്ങളും, ഡെലിവറബിളുകൾ, ടാസ്ക് തലക്കെട്ടുകളും അവ ആർക്കാണ് നൽകിയിരിക്കുന്നത് എന്നതും, RAID ലോഗ്, ബജറ്റ് ആകെത്തുകകൾ, അറിയിച്ച തടസ്സം, സമീപകാല ചരിത്രം - ചോദിക്കുന്നയാൾക്ക് കാണാൻ കഴിയുന്നവ മാത്രം. Brief me അല്ലെങ്കിൽ Draft അമർത്തുന്നതുവരെ ഒന്നും അയയ്ക്കില്ല.',
