        'templates_intro' => 'ഒരാൾ പ്രോജക്റ്റ് സൃഷ്ടിക്കുമ്പോൾ നൽകുന്ന ടെംപ്ലേറ്റുകൾ. ഉപയോഗിക്കാത്ത ബിൽറ്റ്-ഇൻ ടെംപ്ലേറ്റ് മറയ്ക്കാം. സ്വന്തമായി ചേർക്കാൻ, നന്നായി നടന്ന ഒരു പ്രോജക്റ്റ് തുറന്ന് Template അമർത്തുക. ഒന്നിലെ ഉള്ളടക്കം മാറ്റാൻ, അതിൽ നിന്ന് ഒരു പ്രോജക്റ്റ് തുടങ്ങി, പ്രോജക്റ്റ് മാറ്റി, Template അമർത്തി പഴയതിനെ മാറ്റിസ്ഥാപിക്കുക.',
