        'approver_owner' => 'പ്രോജക്റ്റ് മാനേജർ (അല്ലെങ്കിൽ Manage Projects)',
        'approver_managers' => 'Manage Projects ഉള്ളവർ മാത്രം',
        'change_self' => 'നിങ്ങളുടെ സ്വന്തം അഭ്യർത്ഥനകൾ തീരുമാനിക്കുക',
        'change_self_desc' => 'മാറ്റ അഭ്യർത്ഥന ഉന്നയിച്ച വ്യക്തിക്ക് തന്നെ അത് അംഗീകരിക്കാനോ നിരസിക്കാനോ കഴിയുമോ എന്നത്. ഇല്ല എന്നാൽ ഓരോ തവണയും മറ്റൊരാൾ കൂടി നോക്കണം.',
        'change_apply' => 'ഒരു മാറ്റം അംഗീകരിക്കൽ',
        'change_apply_desc' => 'മാറ്റ അഭ്യർത്ഥന അംഗീകരിക്കുമ്പോൾ പ്ലാനിന് എന്ത് സംഭവിക്കുന്നു. പുതിയ ബേസ്‌ലൈൻ എപ്പോഴും എടുക്കും.',
        'apply_baseline' => 'പുതിയ ബേസ്‌ലൈൻ മാത്രം എടുക്കുന്നു - പ്ലാൻ കൈകൊണ്ട് മാറ്റണം',
        'apply_plan' => 'ലക്ഷ്യ അവസാനവും മാറ്റുകയും ചെലവ് ബജറ്റിൽ ചേർക്കുകയും ചെയ്യുന്നു',
        'overdue_digest' => 'കാലാവധി കഴിഞ്ഞ ടാസ്ക് ഡൈജസ്റ്റ്',
        'overdue_digest_desc' => 'ഓരോ പ്രോജക്റ്റ് മാനേജർക്കും അവരുടെ സജീവ പ്രോജക്റ്റിലെ കാലാവധി കഴിഞ്ഞ ടാസ്കുകൾ പട്ടികപ്പെടുത്തിയ ഒരു ബെൽ എത്ര തവണ ലഭിക്കുന്നു. കാലാവധി കഴിഞ്ഞവ ഇല്ലെങ്കിൽ ഒന്നും അയയ്ക്കില്ല.',
        'digest_weekly' => 'ആഴ്ചതോറും, തിങ്കളാഴ്ച',
        'digest_daily' => 'ദിവസേന',
        'digest_off' => 'ഒരിക്കലും വേണ്ട',
        'nudge_days' => 'ഓർമ്മപ്പെടുത്തൽ (ദിവസങ്ങൾക്ക് ശേഷം)',
        'nudge_days_desc' => 'ഒരു നിർദ്ദേശം, മാറ്റ അഭ്യർത്ഥന, ഗേറ്റ് സൈൻ-ഓഫ് അല്ലെങ്കിൽ റിപ്പോർട്ട് ഡ്രാഫ്റ്റ് ഇത്രയും ദിവസം തീരുമാനത്തിനായി കാത്തുനിന്നാൽ, തീരുമാനിക്കേണ്ടവർക്ക് ഒരു ഓർമ്മപ്പെടുത്തൽ ലഭിക്കും - പിന്നീട് ഇത്രയും ദിവസം കൂടുമ്പോഴും. 0 = ഓർമ്മപ്പെടുത്തലുകളില്ല.',
        'assistant_memory' => 'AI അസിസ്റ്റന്റിന്റെ മെമ്മറി',
        'assistant_memory_desc' => 'Ask AI അസിസ്റ്റന്റ് ഒരു പ്രോജക്റ്റിൽ ആരുടെ സംഭാഷണം സൂക്ഷിക്കുന്നു: ഓരോരുത്തർക്കും സ്വന്തം സ്വകാര്യ സംഭാഷണം - അല്ലെങ്കിൽ പ്രോജക്റ്റ് ടീം മുഴുവൻ പങ്കിടുന്ന ഒന്ന്, അങ്ങനെ കഴിഞ്ഞയാൾ നിർത്തിയിടത്തുനിന്ന് ആർക്കും തുടരാം.',
        'memory_person' => 'ഓരോരുത്തർക്കും സ്വന്തം',
        'memory_project' => 'ഒരു പ്രോജക്റ്റിന് ഒന്ന്, പങ്കിട്ടത്',
        'contractor_email' => 'കോൺട്രാക്ടർമാർക്ക് ഇമെയിൽ ചെയ്യുക',
        'contractor_email_desc' => 'ഒരു ടാസ്ക് കോൺട്രാക്ടർക്ക് നൽകുമ്പോൾ - ഒരു വിതരണക്കാരനും അവിടത്തെ ഒരു വ്യക്തിയും - ആ വ്യക്തിക്ക് ഇമെയിൽ ചെയ്യുക: നൽകുമ്പോൾ, അവസാന തീയതിക്ക് രണ്ട് ദിവസം മുമ്പ്, തീയതി കഴിഞ്ഞാൽ ഒരിക്കൽ. ഓഫ്: കോൺട്രാക്ടർ ജോലി ഇവിടെ ട്രാക്ക് ചെയ്യുക മാത്രമേ ചെയ്യൂ, പിന്തുടരേണ്ടത് നിങ്ങളാണ്.',
        'contractor_email_off' => 'ഓഫ് - ട്രാക്ക് ചെയ്യുക മാത്രം',
        'contractor_email_on' => 'ഓൺ - കോൺടാക്റ്റിന് ഇമെയിൽ ചെയ്യുക',
        'toolbox' => 'Overview-ലെ ടൂൾബോക്സ്',
        'toolbox_desc' => 'പ്രോജക്റ്റ് ഇതുവരെ ഉപയോഗിക്കാത്ത ടൂളുകൾ പട്ടികപ്പെടുത്തുന്നു - ഓരോന്നും എന്തിനാണ്, എപ്പോൾ വേണ്ടിവരും, പ്രോജക്റ്റ് തന്നെ നിർദ്ദേശിക്കുന്നവ - കൂടെ Add-ഉം. പ്രോജക്റ്റുകൾ തുടങ്ങുന്നത് അവയുടെ പ്രവർത്തന രീതി ഓണാക്കുന്ന ടൂളുകളോടെയാണ് (Simple: People മാത്രം), അതിനാൽ പ്രോജക്റ്റ് വളരുന്നതിനനുസരിച്ച് തുടക്കക്കാർ ബാക്കിയുള്ളവ പരിചയപ്പെടുന്നു. ഓഫ്: ടൂളുകൾ ഓരോ പ്രോജക്റ്റിന്റെയും Edit ഫോമിൽ മാത്രം സജ്ജമാക്കും.',
        'default_visibility' => 'പുതിയ പ്രോജക്റ്റ് ആർക്ക് കാണാം',
        'default_visibility_desc' => 'അംഗങ്ങൾ മാത്രം: അതിന്റെ പ്രോജക്റ്റ് മാനേജർ, സൃഷ്ടിച്ചയാൾ, അംഗങ്ങൾ (നേരിട്ടോ ഒരു ടീം വഴിയോ), Projects കൈകാര്യം ചെയ്യുന്നവർ എന്നിവർ മാത്രം - HR, സുരക്ഷ അല്ലെങ്കിൽ രഹസ്യ ജോലികൾക്കായി. ഓരോ പ്രോജക്റ്റും അതിന്റെ സ്വന്തം ഫോമിൽ മാറ്റാം.',
        'gate_checklist' => 'തുറന്നിരിക്കുന്ന ഗേറ്റ് ചെക്ക്‌ലിസ്റ്റ് ഇനം',
        'gate_checklist_desc' => 'ചെക്ക്‌ലിസ്റ്റ് പൂർത്തിയാകാത്ത ഒരു ഗേറ്റിൽ ആരെങ്കിലും ഗോ രേഖപ്പെടുത്തിയാൽ എന്ത് സംഭവിക്കുന്നു. സ്റ്റോപ്പ് എപ്പോഴും അനുവദനീയമാണ്.',
        'gatecheck_block' => 'പൂർത്തിയാകുന്നതുവരെ ഗോ തടയുന്നു',
        'gatecheck_warn' => 'ഗോ അനുവദിക്കുന്നു, എന്താണ് തുറന്നിരുന്നതെന്ന് രേഖപ്പെടുത്തുന്നു',
        'benefit_review_months' => 'ബെനിഫിറ്റുകൾ അവലോകനം ചെയ്യുന്നത് ഓരോ',
        'benefit_review_months_desc' => 'മറ്റൊന്ന് പറയുന്നില്ലെങ്കിൽ, ഒരു പുതിയ ബെനിഫിറ്റ് എത്ര മാസത്തെ ഇടവേളയിൽ അവലോകനം ചെയ്യുന്നു. 0 = ഒരു തവണ മാത്രം.',
        'benefit_notify' => 'ബെനിഫിറ്റ് അവലോകന ഓർമ്മപ്പെടുത്തലുകൾ പോകുന്നത്',
        'benefit_notify_desc' => 'ഒരു ബെനിഫിറ്റ് അവലോകനത്തിന് സമയമാകുമ്പോൾ ബെൽ ആരെ അറിയിക്കുന്നു - പ്രോജക്റ്റ് അടച്ചതിന് ശേഷവും.',
        'bnotify_both' => 'അതിന്റെ ഉടമയ്ക്കും പ്രോജക്റ്റ് മാനേജർക്കും',
        'bnotify_owner' => 'അതിന്റെ ഉടമയ്ക്ക് മാത്രം (ഉടമ ഇല്ലെങ്കിൽ പ്രോജക്റ്റ് മാനേജർക്ക്)',
        'proposal_approval' => 'അനുമതി വേണ്ട പുതിയ പ്രോജക്റ്റുകൾ',
        'proposal_approval_desc' => 'അനുമതി വേണ്ട പ്രോജക്റ്റ് ഒരു നിർദ്ദേശമായി തുടങ്ങുന്നു, അനുമതി ലഭിക്കുന്നതുവരെ തുടങ്ങാനാവില്ല. ഇതിനകം സൃഷ്ടിച്ച പ്രോജക്റ്റുകളെ ഒരിക്കലും ബാധിക്കില്ല.',
        'proposal_forms' => 'ഒരു ഫോമിൽ നിർദ്ദേശിച്ചവ',
