        'proposal_off' => 'ഒന്നുമില്ല',
        'proposal_approver' => 'നിർദ്ദേശങ്ങൾക്ക് ആര് അനുമതി നൽകുന്നു',
        'proposal_approver_desc' => 'Projects കൈകാര്യം ചെയ്യുന്നവർക്ക് എപ്പോഴും അനുമതി നൽകാം. നിർദ്ദേശങ്ങൾ പകരം ഒരാൾക്ക് അയയ്ക്കാൻ അയാളുടെ പേര് നൽകുക.',
        'approver2_managers' => 'Projects കൈകാര്യം ചെയ്യുന്നവർ',
        'approver2_person' => 'പേര് നൽകിയ ഒരാൾ',
        'proposal_person' => 'പേര് നൽകിയ വ്യക്തി',
        'proposal_person_desc' => 'നിർദ്ദേശങ്ങൾ പേര് നൽകിയ ഒരാൾക്ക് പോകുമ്പോൾ ഉപയോഗിക്കുന്നു.',
        'nobody' => 'ആരെയും തിരഞ്ഞെടുത്തിട്ടില്ല',
        'proposal_on_approve' => 'ഒരു നിർദ്ദേശത്തിന് അനുമതി നൽകൽ',
        'proposal_on_approve_desc' => 'ഒരു നിർദ്ദേശത്തിന് അനുമതി ലഭിക്കുമ്പോൾ അതിന് എന്ത് സംഭവിക്കുന്നു.',
        'onapprove_proposed' => 'പ്രോജക്റ്റ് മാനേജർ തുടങ്ങാനായി അത് Proposed ആയി തുടരുന്നു',
        'onapprove_active' => 'അത് ഉടൻ തുടങ്ങുന്നു',
        'cost_basis' => 'ചെലവ് അധികമാകാനുള്ള ടോളറൻസ് അളക്കുന്നത്',
        'cost_basis_desc' => 'പ്രോജക്റ്റിന്റെ Overspend allowed-മായി എന്താണ് താരതമ്യം ചെയ്യുന്നത്: ഇതുവരെ ചെലവഴിച്ചത്, അല്ലെങ്കിൽ പ്രോജക്റ്റിന് ഇപ്പോൾ പ്രവചിക്കുന്ന ചെലവ് - ഇത് നേരത്തെ മുന്നറിയിപ്പ് നൽകുന്നു.',
        'basis_actual' => 'ചെലവഴിച്ചത്',
        'basis_forecast' => 'പ്രവചനം',
        'forecast_labour' => 'പ്രവചനത്തിലെ എസ്റ്റിമേറ്റുകൾ',
        'forecast_labour_desc' => 'തുറന്ന ടാസ്കുകളിൽ ഇനിയും കണക്കാക്കിയിട്ടുള്ള മണിക്കൂറുകൾ ഇന്നത്തെ നിരക്കിൽ വിലയിട്ട് പ്രവചനത്തിൽ ഉൾപ്പെടുത്തണോ എന്നത്.',
        'measure_hours' => 'കണക്കാക്കിയ മണിക്കൂറുകൾ',
        'effect_off' => 'ഒന്നുമില്ല',
        'effect_amber' => 'അപകടസാധ്യതയിൽ (മഞ്ഞ)',
        'effect_red' => 'ട്രാക്കിൽ നിന്ന് മാറി (ചുവപ്പ്)',
        'health_milestones' => 'നഷ്ടപ്പെട്ട മൈൽസ്റ്റോൺ പ്രോജക്റ്റിനെ ആക്കുന്നത്',
        'health_milestones_desc' => 'എത്തിച്ചേരാതെ തീയതി കഴിഞ്ഞുപോയ ഒരു മൈൽസ്റ്റോൺ.',
        'health_raid_late' => 'വൈകിയ ഡിപെൻഡൻസിയോ തീരുമാനമോ പ്രോജക്റ്റിനെ ആക്കുന്നത്',
