            'p1' => 'ഓഫീസ് മാറ്റം, ലാപ്ടോപ്പ് മാറ്റിസ്ഥാപിക്കൽ, മെയിൽ മൈഗ്രേഷൻ എന്നിവ ഒരു ടാസ്ക് ആകാൻ കഴിയാത്തത്ര വലുതാണ്, സ്പ്രെഡ്ഷീറ്റിൽ ഒതുക്കാൻ കഴിയാത്തത്ര പ്രധാനവുമാണ്. ഒരു പ്രോജക്റ്റ് അതിനു പിന്നിലെ ടാസ്കുകളെ ഒന്നിച്ചുചേർക്കുകയും ഫേസുകളായി വിഭജിക്കുകയും ആ ടാസ്കുകളിൽ നിന്ന് എത്രത്തോളം പുരോഗമിച്ചു, പ്രശ്നത്തിലാണോ എന്ന് കണക്കാക്കുകയും ചെയ്യുന്നു.',
            'p2' => 'സ്വന്തം പ്രോജക്റ്റ് ആസൂത്രണം ചെയ്യുന്നതിനു മുമ്പ് ഇത് പ്രവർത്തിക്കുന്നത് കാണാൻ, System തുറക്കാൻ അനുമതിയുള്ള ഒരാൾക്ക് **System - Demo data - Tasks and Projects** ഇംപോർട്ട് ചെയ്യാം: പ്രോജക്റ്റ് നടത്താനുള്ള എല്ലാ രീതികളും എല്ലാ നിലകളും ഉൾക്കൊള്ളുന്ന ഒൻപത് പ്രോജക്റ്റുകൾ, അവയുടെ ടാസ്കുകൾ, ചാർട്ടുകൾ, ചരിത്രം എന്നിവയോടൊപ്പം. ആദ്യം Assets, Changes, Tickets, Contracts, Knowledge, CMDB എന്നിവ ഇംപോർട്ട് ചെയ്താൽ പ്രോജക്റ്റുകൾ ആ രേഖകളുമായും ബന്ധിപ്പിക്കപ്പെടും. വീണ്ടും ഇംപോർട്ട് ചെയ്താൽ ഡെമോ പ്രോജക്റ്റുകൾ മാത്രമേ മാറ്റിസ്ഥാപിക്കൂ.',
