            'card_plan_desc' => 'ഫേസുകൾ, ഘട്ടങ്ങൾ അല്ലെങ്കിൽ സ്പ്രിന്റുകൾ, ഓരോന്നിനും സ്വന്തം ടാസ്കുകളും തീയതികളും പുരോഗതിയും.',
            'card_tasks_title' => 'യഥാർത്ഥ ടാസ്കുകൾ',
            'card_tasks_desc' => 'പ്രോജക്റ്റ് ജോലി സാധാരണ ടാസ്കുകൾ തന്നെയാണ്, അതിനാൽ ജോലി ചെയ്യുന്നവർക്ക് അത് Tasks ബോർഡിൽ കാണാം.',
            'card_health_title' => 'ഒറ്റനോട്ടത്തിൽ ആരോഗ്യനില',
            'card_health_desc' => 'ഓരോ പ്രോജക്റ്റിലും ഒരു റിംഗ്: എത്ര പൂർത്തിയായി, ശരിയായ പാതയിലാണോ എന്ന്.',
            'card_method_title' => 'നിങ്ങളുടെ പ്രവർത്തന രീതി',
            'card_method_desc' => 'Simple, Staged അല്ലെങ്കിൽ Agile - പിന്നീട് മനസ്സ് മാറ്റുകയും ചെയ്യാം.',
        ],
        'map' => [
            'nav' => 'എങ്ങനെ ചേരുന്നു',
            'title' => 'എങ്ങനെ ചേരുന്നു',
            'intro' => 'ഒരു പ്രോജക്റ്റിന്റെ ഓരോ ഭാഗവും, എന്തിൽ നിന്ന് എന്ത് ഉണ്ടാകുന്നു എന്നതും - ഇത് പര്യവേക്ഷണം ചെയ്യുക, അല്ലെങ്കിൽ ലക്ഷ്യം മുതൽ ആനുകൂല്യങ്ങൾ വരെ ഒരു പ്രോജക്റ്റിലൂടെ നടക്കുക.',
            'open' => 'മാപ്പ് തുറക്കുക',
            'open_walk' => 'ഒരു പ്രോജക്റ്റിലൂടെ നടക്കുക',
            'p1' => 'ഇതിന് സ്വന്തമായ ഒരു പേജ് ഉണ്ട്, അതിനാൽ മാപ്പിന് മുഴുവൻ സ്ക്രീനും ലഭിക്കും - ശൂന്യമായ പോർട്ട്ഫോളിയോയിൽ നിന്നും Toolbox-ൽ നിന്നും ഇതിലേക്ക് ലിങ്കുണ്ട്. ഏതെങ്കിലും ബോക്സ് തിരഞ്ഞെടുത്താൽ അത് എന്താണെന്നും എവിടെ കണ്ടെത്താമെന്നും ഏത് ടൂൾ അത് ഓണാക്കുന്നുവെന്നും കാണാം; വരകളും ലിസ്റ്റുകളും അത് എന്തിനെ പോഷിപ്പിക്കുന്നുവെന്നും എന്തൊക്കെ അതിനെ പോഷിപ്പിക്കുന്നുവെന്നും കാണിക്കുന്നു. **Walk through a project** ഒരു ഓഫീസ് മാറ്റത്തെ അതിന്റെ ലക്ഷ്യം മുതൽ ആനുകൂല്യങ്ങൾ വരെ പന്ത്രണ്ട് ഘട്ടങ്ങളായി പിന്തുടരുന്നു (ആരോ കീകൾ ഉപയോഗിച്ചും ഇതിലൂടെ നീങ്ങാം). **Show what a project starts with** ഒരു പ്രവർത്തന രീതി തുടക്കത്തിൽ ഒഴിവാക്കുന്ന ഭാഗങ്ങൾ മങ്ങിക്കുന്നു - Simple പ്രോജക്റ്റ് വളരെ കുറച്ചേ കൊണ്ട് തുടങ്ങൂ, പ്രോജക്റ്റിന് ആവശ്യമാകുമ്പോൾ അതിന്റെ Overview-ലെ Toolbox ബാക്കിയുള്ളവ ചേർക്കും.',
            'noscript' => 'ഇന്ററാക്ടീവ് മാപ്പിന് JavaScript ആവശ്യമാണ്. ഓരോ ഭാഗവും താഴെയുള്ള വിഭാഗങ്ങളിലും വിവരിച്ചിട്ടുണ്ട്.',
        ],
        'portfolio' => [
            'nav' => 'പോർട്ട്ഫോളിയോ',
            'title' => 'പോർട്ട്ഫോളിയോ',
            'intro' => 'ഓരോ പ്രോജക്റ്റും ഒരു കാർഡായി.',
            'p1' => 'Projects തുറക്കുന്നത് പോർട്ട്ഫോളിയോയിലാണ്: ഓരോ പ്രോജക്റ്റിനും ഒരു കാർഡ്, അതിന്റെ ഉടമ തിരഞ്ഞെടുത്ത നിറത്തിലും ഐക്കണിലും. റിംഗ് എത്ര ജോലി പൂർത്തിയായി എന്ന് കാണിക്കുകയും അതിന്റെ ആരോഗ്യനില അനുസരിച്ച് നിറം മാറുകയും ചെയ്യുന്നു; അതിനു താഴെ ലക്ഷ്യ തീയതി, ആരാണ് നയിക്കുന്നത്, ഇപ്പോൾ എന്താണ് നടക്കുന്നത് എന്നിവയുണ്ട്.',
            'p2' => 'ഇടതുവശത്തെ വ്യൂകൾ പതിവ് ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുന്നു - എന്താണ് സജീവം, ഞാൻ എന്താണ് നയിക്കുന്നത്, എന്തിനാണ് ശ്രദ്ധ വേണ്ടത്, എന്താണ് പൂർത്തിയായത് - മുകളിലെ ടൈലുകൾ അവയെല്ലാം ചേർത്ത് പ്രധാനപ്പെട്ടത് എണ്ണുന്നു. ഒരു പ്രോജക്റ്റ് തുടങ്ങാൻ **New** അമർത്തുക.',
            'p3' => 'ടൈലുകൾക്ക് താഴെ, സജീവ പ്രോജക്റ്റുകളുടെ നില ഒരു ബാർ കാണിക്കുന്നു - ശരിയായ പാതയിൽ, അപകടത്തിൽ, പാതയ്ക്ക് പുറത്ത്, അല്ലെങ്കിൽ ഇതുവരെ ആരോഗ്യനിലയില്ല - ഓരോന്നിന്റെയും എണ്ണത്തോടെ. **Sort** കാർഡുകളെ ലക്ഷ്യ തീയതി, മുൻഗണന, ആരോഗ്യനില അല്ലെങ്കിൽ പേര് അനുസരിച്ച് ക്രമീകരിക്കുന്നു (Projects - Settings - General തുടക്ക ക്രമം നിശ്ചയിക്കുന്നു), **Roadmap** കാർഡുകൾക്ക് പകരം കലണ്ടറിൽ ഓരോ പ്രോജക്റ്റിനും ഒരു ബാർ കാണിക്കുന്നു: ആരംഭം മുതൽ ലക്ഷ്യ പൂർത്തീകരണം വരെ, പൂർത്തിയായ ജോലിക്ക് കൂടുതൽ കടുത്ത നിറത്തിൽ, അടുത്ത മൈൽസ്റ്റോണോടെ. ഓരോ പ്രോജക്റ്റിനും ഒരു **priority** ഉണ്ട് - Low, Medium, High അല്ലെങ്കിൽ Critical, അല്ലെങ്കിൽ ക്രമീകരണങ്ങളിൽ നിന്നുള്ള നിങ്ങളുടെ സ്വന്തം നാല് വാക്കുകൾ - Medium അല്ലാത്തപ്പോൾ അത് കാർഡിൽ കാണിക്കും.',
            'p4' => '**Charts** (Cards, Roadmap എന്നിവയുടെ അടുത്ത്) വ്യൂവിലെ പ്രോജക്റ്റുകളെ ഒന്നിച്ച് വരയ്ക്കുന്നു: പ്രോജക്റ്റ് അനുസരിച്ച് പുരോഗതി, ബജറ്റും യഥാർത്ഥ ചെലവും (ഓരോ കറൻസിക്കും ഒരു ചാർട്ട്, അധിക ചെലവ് രേഖപ്പെടുത്തി), തുറന്നിരിക്കുന്ന എല്ലാ റിസ്കുകളുടെയും റിസ്ക് ഹീറ്റ് മാപ്പ് - അവ ലിസ്റ്റ് ചെയ്യാൻ ഒരു ചതുരം തിരഞ്ഞെടുക്കുക - പ്രോജക്റ്റുകളിലുടനീളമുള്ള ഓരോ മൈൽസ്റ്റോണും, എത്തിയത്, നഷ്ടമായത് അല്ലെങ്കിൽ വരാനിരിക്കുന്നത്. ഓരോ ചാർട്ടിനും ഒരു **Table** ഉണ്ട്.',
            'p5' => '**Export** വ്യൂവിലെ പ്രോജക്റ്റുകളെ - നിങ്ങൾ തിരഞ്ഞെടുത്ത വ്യൂ, തിരയൽ, ക്രമം എന്നിവയ്ക്ക് ശേഷം - ഒരു Excel വർക്ക്ബുക്കായോ CSV ഫയലായോ ഡൗൺലോഡ് ചെയ്യുന്നു: നില, മുൻഗണന, ആരോഗ്യനില, പുരോഗതി, പ്രോജക്റ്റ് മാനേജർ, തീയതികൾ, ടാസ്കുകൾ, മൈൽസ്റ്റോണുകൾ, ഓരോ പ്രോജക്റ്റിന്റെയും സ്വന്തം കറൻസിയിലെ ബജറ്റ്. പ്രോജക്റ്റുകളൊന്നുമില്ലാത്ത വ്യൂ ഒന്നും എക്സ്പോർട്ട് ചെയ്യില്ല.',
        ],
        'project' => [
            'nav' => 'ഒരു പ്രോജക്റ്റ്',
            'title' => 'ഒരു പ്രോജക്റ്റിന്റെ പേജ്',
            'intro' => 'ബാനർ, തുടർന്ന് Overview, Plan, Timeline, പ്രോജക്റ്റിന്റെ ടൂളുകൾ, Documents, Reports, Connections, History.',
            'p1' => 'ബാനർ പ്രോജക്റ്റിന്റെ പേര്, അതിന്റെ ലക്ഷ്യം (പൂർത്തിയായാൽ എങ്ങനെയിരിക്കും), നില, നടത്തുന്ന രീതി, ആരാണ് നയിക്കുന്നത്, തീയതികൾ, ആരോഗ്യ റിംഗ് എന്നിവ കാണിക്കുന്നു. **Edit** നിലയുൾപ്പെടെ എന്തും മാറ്റുന്നു: ഒരു പ്രോജക്റ്റ് Closed ആക്കിയാൽ ആരും യഥാർത്ഥ പൂർത്തീകരണ തീയതി നൽകിയിട്ടില്ലെങ്കിൽ ഇന്നത്തെ തീയതി അതായി ചേർക്കപ്പെടും.',
            'p2' => 'Overview സംഖ്യകൾ ശേഖരിക്കുന്നു: **Progress over time** (ഒരു burn-up: പ്ലാനിലെ ഓരോ ടാസ്കും പൂർത്തിയായവയ്ക്കെതിരെ, ദിവസമോ ആഴ്ചയോ അനുസരിച്ച്, ലക്ഷ്യ പൂർത്തീകരണം അടയാളപ്പെടുത്തി - അത് മാത്രം കാണാൻ ഒരു ഫേസ് തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ ടാസ്കുകൾക്ക് പകരം കണക്കാക്കിയ മണിക്കൂറുകൾ എണ്ണുക), ഇപ്പോൾ എന്താണ് നടക്കുന്നത്, അടുത്തതായി എന്താണ് വരേണ്ടത്, ഏറ്റവും പുതിയ മാറ്റങ്ങൾ. Plan, Timeline എന്നിവയ്ക്ക് ശേഷം പ്രോജക്റ്റ് ഉപയോഗിക്കുന്ന ഓരോ ടൂളിനും ഒരു ടാബ് വരുന്നു - People, Scope, RACI, RAID, Gates, Budget, Change control, Benefits, താഴെ വിവരിച്ചിട്ടുണ്ട് - പിന്നീട് **Documents** (പ്ലാനുകൾ, ഡിസൈനുകൾ, സൈൻ-ഓഫ് കത്തുകൾ: അപ്‌ലോഡ് ചെയ്ത ഫയൽ അല്ലെങ്കിൽ അത് ഉള്ളിടത്തേക്കുള്ള ലിങ്ക്), Reports, Connections. എല്ലാ ടൂളുകളും ഓണാക്കിയാൽ ടാബ് ബാർ വശത്തേക്ക് സ്ക്രോൾ ചെയ്യും. മാറിയതെല്ലാം ആര് മാറ്റി എന്നതോടൊപ്പം History പട്ടികപ്പെടുത്തുന്നു.',
            'p3' => '**Progress over time**-ന് (burn-up, അല്ലെങ്കിൽ **Burndown** - അവസാനം വരെയുള്ള ആദർശ രേഖയ്ക്കെതിരെ ബാക്കിയുള്ളത്) താഴെ Overview-ൽ **Task status** (ഓരോ ഘട്ടത്തിനും ഒരു ബാർ: നിങ്ങളുടെ ഓരോ ടാസ്ക് നിലയിലും എത്ര ടാസ്കുകളുണ്ട്, എത്രയെണ്ണം കാലാവധി കഴിഞ്ഞു അല്ലെങ്കിൽ മറ്റൊരു ടാസ്കിനായി കാത്തിരിക്കുന്നു), **Progress by stage**, **Flow over time** - കുമുലേറ്റീവ് ഫ്ലോ ഡയഗ്രം: ഓരോ നിലയിലെയും ടാസ്കുകൾ, ദിവസം തോറും എന്നിവയുണ്ട്. തുടർച്ചയായി വീതി കൂടുന്ന ഒരു ബാൻഡ് അവിടെ ജോലി കുമിഞ്ഞുകൂടുന്നു എന്നാണ്. 3.3.0 മുതൽ നിലകൾ ദിവസത്തിൽ ഒരിക്കൽ രേഖപ്പെടുത്തുന്നു; അതിനു മുമ്പ് ടാസ്കുകൾ സൃഷ്ടിച്ചതും പൂർത്തിയാക്കിയതും എപ്പോൾ എന്നത് മാത്രമേ അറിയൂ, അത് ചാരനിറത്തിൽ കാണിക്കുന്നു.',
            'p4' => 'ചാർട്ടുകൾക്ക് മുകളിൽ, ആർക്കെങ്കിലും ശ്രദ്ധ വേണ്ടത് എന്താണെന്ന് Overview പറയുന്നു, ബാധകമാകുമ്പോൾ മാത്രം: നഷ്ടമായ മൈൽസ്റ്റോൺ, തീയതി കഴിഞ്ഞ ഡിപ്പൻഡൻസി അല്ലെങ്കിൽ തീരുമാനം, ദിവസം എത്തിയ ബെനിഫിറ്റ് അവലോകനങ്ങൾ, തീരുമാനത്തിനായി കാത്തിരിക്കുന്ന മാറ്റ അഭ്യർത്ഥനകൾ, RAID ലോഗിൽ എസ്കലേറ്റ് ചെയ്ത എന്തും - ഓരോന്നിനും **See all**. പിന്നെ, നിർദ്ദേശിക്കപ്പെട്ട പ്രോജക്റ്റിൽ **Proposal** പാനൽ (കാത്തിരിക്കുമ്പോൾ Approve, Reject), **Toolbox** (Tools കാണുക), AI **Briefing** എന്നിവ.',
        ],
        'plan' => [
            'nav' => 'പ്ലാൻ',
            'title' => 'പ്ലാൻ ഉണ്ടാക്കൽ',
            'intro' => 'ആദ്യം ഫേസുകൾ, പിന്നെ ടാസ്കുകൾ.',
            'p1' => 'Plan ടാബ് ഓരോ ഫേസിനെയും (അല്ലെങ്കിൽ ഘട്ടം, അല്ലെങ്കിൽ സ്പ്രിന്റ്) ടാസ്കുകളുടെ ഒരു ലെയ്നായി കാണിക്കുന്നു, അതിന്റെ തീയതികൾ, നില, എത്ര ടാസ്കുകൾ പൂർത്തിയായി എന്നിവയോടെ. ഇതുവരെ ഒരു ഫേസിലും ഇല്ലാത്ത ടാസ്കുകൾ താഴെ കിടക്കും.',
            'p2' => 'ഒരു ലെയ്നിനു താഴെയുള്ള ബോക്സിൽ ടൈപ്പ് ചെയ്ത് ടാസ്ക് ചേർക്കുക - ആരാണ് ചെയ്യുന്നതെന്നും എപ്പോൾ വേണമെന്നും വേണമെങ്കിൽ തിരഞ്ഞെടുക്കാം. ഒരു ടാസ്ക് മാറ്റാൻ മറ്റൊരു ലെയ്നിലേക്ക് വലിച്ചിടുക, അല്ലെങ്കിൽ ലെയ്നിലെ ക്രമം ശരിയാക്കാൻ മുകളിലേക്കും താഴേക്കും വലിക്കുക - എവിടെ വീഴും എന്ന് ഒരു വര കാണിക്കും. കീബോർഡിൽ നിന്ന്, ടാസ്ക്&rsquo;ന്റെ ഹാൻഡിൽ ഫോക്കസ് ചെയ്ത് മുകളിലേക്കോ താഴേക്കോ ഉള്ള ആരോ അമർത്തുക; ഫോണിൽ, ഓരോ ടാസ്കിലെയും നീക്കുക ബട്ടണിൽ Up, Down എന്നിവയുണ്ട്. ഒരു ടാസ്കിൽ ക്ലിക്ക് ചെയ്താൽ അത് Tasks ബോർഡിൽ തുറക്കും, അവിടെ മറ്റേതൊരു ടാസ്കും പോലെ എഡിറ്റ് ചെയ്യാം.',
            'p3' => 'ഒരു ഫേസിലെ ജോലി തുടങ്ങുമ്പോൾ അതിൽ **Start** അമർത്തുക, പൂർത്തിയാകുമ്പോൾ **Finish**. ടാസ്ക് വരിയുടെ അറ്റത്തുള്ള ക്രോസ് അതിനെ പ്രോജക്റ്റിൽ നിന്ന് എടുത്തുമാറ്റുന്നു; ടാസ്ക് തന്നെ സൂക്ഷിക്കപ്പെടും.',
            'p4' => 'മൈൽസ്റ്റോണുകൾ പ്രോജക്റ്റ് വാഗ്ദാനം ചെയ്യുന്ന തീയതികളാണ് - മാറ്റ ദിവസം, ഗോ-ലൈവ്, ബോർഡിന്റെ സൈൻ-ഓഫ്. ഒന്ന് ചേർക്കാൻ Plan ടാബിൽ **Milestone** അമർത്തുക, ഒരു ഫേസിലോ മുഴുവൻ പ്രോജക്റ്റിനോ. ഓരോ ഫേസും അതിന്റെ മൈൽസ്റ്റോണുകളെ ഡയമണ്ടുകളായി കാണിക്കുന്നു; അത് സംഭവിക്കുമ്പോൾ **Reached** ടിക്ക് ചെയ്യുക. എത്താതെ തീയതി കടന്നുപോയ മൈൽസ്റ്റോൺ നഷ്ടമായതാണ്, പ്രോജക്റ്റിനെ ആമ്പർ നിറമാക്കും.',
            'step1' => 'പോർട്ട്ഫോളിയോയിൽ **New** അമർത്തുക, പ്രോജക്റ്റിന് ഒരു പേരും ലക്ഷ്യവും നൽകുക, അത് എങ്ങനെ നടത്തണമെന്ന് തിരഞ്ഞെടുക്കുക.',
            'step2' => 'Plan ടാബിൽ, ജോലി വിഭജിക്കപ്പെടുന്ന ഫേസുകൾ ചേർക്കുക.',
            'step3' => 'ഓരോ ഫേസിനും കീഴിൽ ടാസ്കുകൾ ചേർക്കുക, ആരാണ് ചെയ്യുന്നതെന്നും എപ്പോഴെന്നും സഹിതം.',
            'step4' => 'ആദ്യ ഫേസ് തുടങ്ങുക. അതിനുശേഷം റിംഗും ആരോഗ്യനിലയും സ്വയം കാലികമായി തുടരും.',
        ],
        'timeline' => [
            'nav' => 'Timeline',
            'title' => 'Timeline',
            'intro' => 'മുഴുവൻ പ്ലാനും കലണ്ടറിനെതിരെ.',
            'p1' => 'Timeline ടാബ് പ്ലാനിനെ ഒരു Gantt ചാർട്ടായി വരയ്ക്കുന്നു: ഓരോ ഫേസും ഘട്ടവും സ്പ്രിന്റും അതിന്റെ തീയതികളിലൂടെയുള്ള ഒരു ബാൻഡാണ്, അതിന്റെ ടാസ്കുകൾ ആരംഭം മുതൽ അവസാന തീയതി വരെയുള്ള ബാറുകളാണ്, മൈൽസ്റ്റോണുകൾ ഡയമണ്ടുകളാണ് - എത്തിയാൽ പച്ച, നഷ്ടമായാൽ ചുവപ്പ്. ഒരു വര ഇന്നിനെ അടയാളപ്പെടുത്തുന്നു, മറ്റൊന്ന് ലക്ഷ്യ പൂർത്തീകരണത്തെ.',
            'p2' => 'മൗസ് ഉപയോഗിച്ച്, ഒരു ടാസ്കോ ഫേസോ നീക്കാൻ ബാർ വലിക്കുക, അല്ലെങ്കിൽ എപ്പോൾ തുടങ്ങണം അവസാനിക്കണം എന്ന് മാറ്റാൻ ഏതെങ്കിലും അറ്റം വലിക്കുക; ഒരു മൈൽസ്റ്റോൺ നീക്കാൻ ഡയമണ്ട് വലിക്കുക. ഓരോ നീക്കവും ഉടൻ സേവ് ചെയ്യപ്പെടുകയും കൈകൊണ്ട് എഡിറ്റ് ചെയ്യുന്ന അതേ നിയമങ്ങളിലൂടെ പോകുകയും ചെയ്യുന്നു, അതിനാൽ Tasks ബോർഡും Calendar-ഉം ആരോഗ്യനിലയും അതിനൊപ്പം മാറുന്നു. പകരം തുറക്കാൻ ഒരു ബാറിൽ ക്ലിക്ക് ചെയ്യുക. തീയതികളില്ലാത്ത ടാസ്കുകൾ വരയ്ക്കില്ല; എത്രയെണ്ണമുണ്ടെന്ന് ടാബ് പറയും.',
            'p3' => 'സൂം ചെയ്യാൻ **Days**, **Weeks** അല്ലെങ്കിൽ **Months** തിരഞ്ഞെടുക്കുക. ഫോണിൽ ചാർട്ട് വശത്തേക്ക് സ്ക്രോൾ ചെയ്യും; കാര്യങ്ങൾ നീക്കുന്നത് അവയിൽ തൊട്ട് തീയതികൾ മാറ്റിയാണ്.',
            'p4' => '**Dependencies.** ടാസ്കിന്റെ വരിയിലെ ലിങ്ക് ബട്ടൺ അത് എന്തിനായി കാത്തിരിക്കുന്നു എന്ന് പറയുന്നു: മറ്റൊരു ടാസ്ക് പൂർത്തിയാകുന്നതുവരെ ഒരു ടാസ്കിന് തുടങ്ങാനാവില്ല, ആവശ്യമെങ്കിൽ കുറച്ച് ദിവസത്തെ ഇടവേളയോടെ. ചാർട്ടിൽ അമ്പുകൾ അവയെ ബന്ധിപ്പിക്കുന്നു - പ്ലാൻ ഏറ്റുമുട്ടുന്നിടത്ത് (മറ്റേത് തീരേണ്ടതിനു മുമ്പ് ഇത് തുടങ്ങുന്നു) ചുവപ്പും ഡാഷുമായി. **Critical path** സ്ലാക്ക് ഇല്ലാത്ത ടാസ്കുകളെ തിരഞ്ഞെടുക്കുന്നു - അവ ഏതു ദിവസം വൈകിയാലും പൂർത്തീകരണം വൈകും - ബാക്കിയുള്ളവയെ മങ്ങിക്കുന്നു. ലൂപ്പ് നിരസിക്കപ്പെടും. Plan-ൽ, കാത്തിരിക്കുന്ന എന്തെങ്കിലും പൂർത്തിയാകാത്തപ്പോൾ ടാസ്ക് **Waiting on 1** കാണിക്കുന്നു, അതിന്റെ തീയതികൾ പ്രവർത്തിക്കാത്തപ്പോൾ **Clash** കാണിക്കുന്നു.',
        ],
        'capacity' => [
            'nav' => 'Capacity',
            'title' => 'എസ്റ്റിമേറ്റുകളും കപ്പാസിറ്റിയും',
            'intro' => 'വരുംയാഴ്ചകളിൽ ആർക്കാണ് ഇടമുള്ളത്, ആരാണ് കൂടുതൽ ഏറ്റെടുത്തിരിക്കുന്നത്.',
            'p1' => 'ഒരു ടാസ്കിന് **estimate** നൽകുക - അതിന് എത്ര മണിക്കൂർ എടുക്കണം - Plan വരിയിലെ ബോക്സിൽ, അല്ലെങ്കിൽ Tasks ബോർഡിലെ ടാസ്ക് വിൻഡോയിൽ. ഓരോ ലെയ്നും Overview-ഉം പിന്നീട് കണക്കാക്കിയ സമയത്തിനെതിരെ ലോഗ് ചെയ്ത സമയം കാണിക്കുന്നു, കണക്കാക്കിയതിലും കൂടുതൽ സമയം ലോഗ് ചെയ്താൽ വരി ചുവപ്പാകുന്നു.',
            'p2' => 'Projects-ന്റെ മുകളിലുള്ള **Capacity** പേജിൽ പ്രോജക്റ്റ് ജോലിയുള്ള ഓരോ വ്യക്തിക്കും ഒരു വരിയും ഓരോ ആഴ്ചയ്ക്കും ഒരു കോളവും ഉണ്ട്. ഒരു ആഴ്ചയിലെ ലോഡ് എന്നത് അവർക്ക് ബാക്കിയുള്ള പ്രോജക്റ്റ് ജോലിയാണ് - ഓരോ ടാസ്കിന്റെയും എസ്റ്റിമേറ്റിൽ നിന്ന് ഇതിനകം ലോഗ് ചെയ്ത സമയം കുറച്ച്, അതിന്റെ ആരംഭം (അല്ലെങ്കിൽ ഇന്ന്) മുതൽ അവസാന തീയതി വരെയുള്ള ജോലി ദിവസങ്ങളിൽ വിതരണം ചെയ്തത് - കൂടാതെ സർവീസ്-ഡെസ്ക് റോട്ടയിലെ അവരുടെ ഷിഫ്റ്റുകളും, ആഴ്ചയിൽ അവർ ജോലി ചെയ്യുന്ന മണിക്കൂറുകൾക്കെതിരെ. പച്ച എന്നാൽ ഇടമുണ്ട്, ആമ്പർ എന്നാൽ ഞെരുങ്ങിയിരിക്കുന്നു, ചുവപ്പ് എന്നാൽ അമിതമായി ഏറ്റെടുത്തിരിക്കുന്നു. പിന്നിലുള്ള ടാസ്കുകൾ കാണാൻ ഒരു വരി തുറക്കുക.',
            'p3' => 'ആഴ്ചകൾക്കരികിൽ ഓരോ വ്യക്തിക്കും എത്ര സജീവ പ്രോജക്റ്റുകളിൽ തുറന്ന ജോലിയുണ്ട് (മൂന്നോ അതിലധികമോ ആയാൽ അടയാളപ്പെടുത്തും), അവരുടെ തുറന്ന ടിക്കറ്റുകൾ, അവസാന തീയതിയില്ലാത്ത ജോലി എന്നിവയുണ്ട്. എസ്റ്റിമേറ്റ് ഇല്ലാത്ത ടാസ്കുകൾ എണ്ണും പക്ഷേ കൂട്ടില്ല, അതിനാൽ എത്രയെണ്ണമുണ്ടെന്ന് പേജ് പറയുന്നു - അറിയാത്ത ജോലി ഒരു റിസ്കാണ്, ഒന്നുമല്ലാത്തതല്ല. **Projects - Settings - Health** ഒരു ആഴ്ചയിലെ മണിക്കൂറുകൾ (37.5), ഒരു ആഴ്ച ആമ്പറാകുന്നത് എപ്പോൾ (85%), എത്ര പ്രോജക്റ്റുകൾ എന്നാൽ നിരവധി, ഏതൊക്കെ ദിവസങ്ങൾ ജോലി ദിവസങ്ങൾ, റോട്ട ഷിഫ്റ്റുകൾ കണക്കാക്കണോ (ഓൺ-കോൾ-മാത്രം റോട്ടയ്ക്ക് ഇത് ഓഫാക്കുക) എന്നിവ നിശ്ചയിക്കുന്നു.',
        ],
        'methods' => [
            'nav' => 'പ്രവർത്തന രീതികൾ',
            'title' => 'Simple, Staged, Agile',
            'intro' => 'ഒരു പ്രോജക്റ്റ്, അതിനെ കാണാൻ മൂന്ന് വഴികൾ.',
            'p1' => 'ഒരു പ്രോജക്റ്റ് എങ്ങനെ നടത്തുന്നു എന്നത് അതിന്റെ ടൈം ബോക്സുകൾക്ക് എന്ത് പേര് വിളിക്കുന്നു, അവ എങ്ങനെ പെരുമാറുന്നു എന്ന് നിശ്ചയിക്കുന്നു. അടിയിൽ, ഓരോ പ്രോജക്റ്റും ഒരേ രീതിയിലാണ് നിർമ്മിച്ചിരിക്കുന്നത്, അതുകൊണ്ടാണ് മനസ്സ് മാറ്റുന്നത് സുരക്ഷിതമായത്.',
            'p2' => 'പകുതിയിൽ രീതി മാറ്റിയാൽ ഒന്നും നഷ്ടപ്പെടില്ല. പൂർത്തിയായ ഫേസുകൾ നടത്തിയ പേര് നിലനിർത്തുന്നു, തുറന്നവ പുതിയ രീതിയുടെ പേര് സ്വീകരിക്കുന്നു, മാറ്റം പ്രോജക്റ്റിന്റെ ചരിത്രത്തിൽ രേഖപ്പെടുത്തുന്നു. പുതിയ രീതി ഒരു സമയം ഒരു ടൈം ബോക്സ് മാത്രം പുരോഗതിയിൽ അനുവദിക്കുന്നുവെങ്കിൽ, ഏറ്റവും ആദ്യത്തേത് പുരോഗതിയിൽ തുടരുകയും ബാക്കിയുള്ളവ ആസൂത്രണം ചെയ്തതിലേക്ക് മടങ്ങുകയും ചെയ്യും.',
            'simple_d' => 'ഫേസുകളും ടാസ്കുകളും. എത്ര ഫേസുകൾ വേണമെങ്കിലും ഒരേ സമയം പുരോഗതിയിലാകാം.',
            'staged_d' => 'അടുത്തത് തുടങ്ങുന്നതിനു മുമ്പ് ഒരു സമയം ഒന്നായി പൂർത്തിയാക്കുന്ന ഘട്ടങ്ങൾ, PRINCE2 ശൈലിയിൽ - ഒരു ബോർഡിന് റിപ്പോർട്ട് ചെയ്യുന്ന പ്രോജക്റ്റുകൾക്ക്.',
            'agile_d' => 'സ്പ്രിന്റുകൾ, ഒരു സമയം ഒന്ന് - പഠിക്കുന്നതിനനുസരിച്ച് മാറുന്ന ജോലിക്ക്.',
        ],
        'tools' => [
            'nav' => 'ടൂളുകൾ',
            'title' => 'ഒരു പ്രോജക്റ്റിന്റെ ടൂളുകളും അവ ക്രമീകരിക്കലും',
            'intro' => 'പ്രോജക്റ്റ് നടത്തുന്ന ഓരോ രീതിയും അതിന്റേതായ ഒരു സെറ്റ് ഓണാക്കുന്നു.',
            'p1' => 'ഒരു പ്രോജക്റ്റിന് എട്ട് ടൂളുകൾ ഉപയോഗിക്കാം, ഓരോന്നിനും സ്വന്തം ടാബ്: People, Scope, RACI, RAID, Gates, Budget, Change control, Benefits. അത് എങ്ങനെ നടത്തുന്നു എന്നത് തുടക്കത്തിൽ ഏതൊക്കെ ഓണായിരിക്കും എന്ന് നിശ്ചയിക്കുന്നു:',
            'p2' => 'ഒരു പ്രോജക്റ്റ് ക്രമീകരിക്കാൻ, അത് **Edit** ചെയ്ത് **Tools**-ന് കീഴിലെ ടൂളുകൾ ടിക്ക് ചെയ്യുകയോ ടിക്ക് മാറ്റുകയോ ചെയ്യുക (ഈ വിഭാഗം എഡിറ്റ് ചെയ്യുമ്പോൾ കാണും, സൃഷ്ടിക്കുമ്പോൾ കാണില്ല). ഒരു ടൂൾ ഓഫാക്കുന്നത് അതിന്റെ ടാബ് മറയ്ക്കുക മാത്രമേ ചെയ്യൂ: അതിലുള്ള ഒന്നും ഇല്ലാതാക്കില്ല, വീണ്ടും ഓണാക്കിയാൽ എല്ലാം തിരിച്ചുവരും. അതേ ഡയലോഗിൽ പ്രോജക്റ്റ് നടത്തുന്ന രീതി മാറ്റിയാൽ ടൂളുകൾ പുതിയ രീതിയുടെ സ്വന്തം സെറ്റിലേക്ക് തിരിച്ചുപോകും.',
            'p3' => 'Overview-ലെ **The Toolbox** പ്രോജക്റ്റ് ഇതുവരെ ഉപയോഗിക്കാത്ത ടൂളുകൾ പട്ടികപ്പെടുത്തുന്നു - ഓരോന്നും എന്തിനാണ്, എപ്പോൾ വേണ്ടിവരും - അതിനാൽ ഒരു Simple പ്രോജക്റ്റിന് ആവശ്യമുള്ളപ്പോൾ ടൂളുകൾ വളർത്താം. പ്രോജക്റ്റ് തന്നെ നിർദ്ദേശിക്കുന്നവ ആദ്യം വരും, കാരണത്തോടെ **Suggested** എന്ന് അടയാളപ്പെടുത്തി: മൂന്നോ അതിലധികമോ ഘട്ടങ്ങൾ Gates നിർദ്ദേശിക്കുന്നു, ഇതിനകം നീങ്ങിയ ലക്ഷ്യ തീയതി Change control നിർദ്ദേശിക്കുന്നു, കാലാവധി കഴിഞ്ഞ ടാസ്ക് RAID നിർദ്ദേശിക്കുന്നു. **Add** Edit ചെയ്യുന്നതുപോലെ തന്നെ ടൂൾ ഓണാക്കുന്നു (RACI ചേർത്താൽ People, Scope എന്നിവയും ചേർക്കപ്പെടും, കാരണം മാട്രിക്സ് അവയിൽ നിന്നാണ് നിർമ്മിക്കുന്നത്). **Hide** നിങ്ങളുടെ ബ്രൗസറിൽ ആ പ്രോജക്റ്റിന് അത് മറയ്ക്കുന്നു. പ്രോജക്റ്റ് മാറ്റാൻ അനുമതിയുള്ളവർക്ക് മാത്രമേ ഇത് കാണൂ, അത് Closed ആയ ശേഷം കാണില്ല. **Projects - Settings - General - Toolbox on the Overview** എല്ലാവർക്കും ഇത് ഓഫാക്കുന്നു.',
        ],
        'people' => [
            'nav' => 'People',
            'title' => 'ആളുകളും റോളുകളും',
            'intro' => 'പ്രോജക്റ്റിൽ ആരൊക്കെയുണ്ട്, ഓരോരുത്തരുടെയും പങ്ക് എന്താണ്.',
            'p1' => 'People ടാബിൽ, **Add someone** ഒരു അനലിസ്റ്റിനെയോ ടീമിനെയോ People-ൽ നിന്നുള്ള ഒരു വ്യക്തിയെയോ ഒരു റോളോടെ പ്രോജക്റ്റിൽ ചേർക്കുന്നു. അനലിസ്റ്റ് അക്കൗണ്ട് ഇല്ലാത്ത ബിസിനസ് സ്പോൺസർക്കോ പ്രധാന ഉപയോക്താവിനോ People-ൽ നിന്നുള്ള വ്യക്തി അനുയോജ്യമാണ്; ഒന്നിലധികം കമ്പനികളുള്ള ഇൻസ്റ്റലേഷനിൽ അവർ പ്രോജക്റ്റിന്റെ കമ്പനിയിൽ ഉൾപ്പെട്ടിരിക്കണം. ആരെയും രണ്ടുതവണ ചേർക്കാനാവില്ല.',
            'p2' => 'റോളുകൾ **Projects - Settings - Roles**-ൽ നിന്ന് വരുന്നു, അത് PRINCE2 ശൈലിയിലുള്ള റോളുകളോടെ തുടങ്ങുന്നു (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance, Project Support) കൂടാതെ Team member, Stakeholder എന്നിവയും.',
            'p3' => 'പ്രോജക്റ്റിലെ ആളുകളാണ് അതിന്റെ RACI മാട്രിക്സിന്റെ കോളങ്ങൾ, അതിനാൽ ഒരാളെ നീക്കിയാൽ അവരുടെ RACI അക്ഷരങ്ങളും നീങ്ങും; അവർക്ക് നൽകിയ ടാസ്കുകൾ മാറില്ല. ഒരു പ്രോജക്റ്റിൽ ഉണ്ടായിരിക്കുന്നത് അനുമതികൾക്കും കണക്കാക്കും: അംഗമായ അല്ലെങ്കിൽ അംഗമായ ടീമിലുള്ള അനലിസ്റ്റ് പ്രോജക്റ്റിന്റെ ടീമിന്റെ ഭാഗമാണ് (Settings and permissions കാണുക). People-ൽ നിന്ന് ചേർത്ത വ്യക്തിക്ക് പ്രോജക്റ്റ് അവരുടെ People പേജിൽ കാണാം, അവരുടെ റോളും അവർ എന്തിൽ Responsible, Accountable, Consulted അല്ലെങ്കിൽ Informed ആണെന്നും സഹിതം.',
            'p4' => '**Who can see it** (പ്രോജക്റ്റിന്റെ ഫോമിൽ): **Everyone with Projects**, അല്ലെങ്കിൽ **Members only** - അതിന്റെ പ്രോജക്റ്റ് മാനേജർ, സൃഷ്ടിച്ചയാൾ, അംഗങ്ങൾ (നേരിട്ടോ ടീം വഴിയോ), Projects മാനേജ് ചെയ്യുന്നവർ എന്നിവർ മാത്രം. HR, സുരക്ഷ അല്ലെങ്കിൽ രഹസ്യ ജോലികൾക്ക്. മറ്റെല്ലാവർക്കും members-only പ്രോജക്റ്റ് നിലവിലില്ല: പോർട്ട്ഫോളിയോ, തിരയൽ, People, Watchtower, Warbot, API എന്നിവയിൽ ഇല്ല, അതിന്റെ തീയതികൾ പങ്കിട്ട Calendar-ൽ നിന്ന് ഒഴിവാകും. Capacity ഇപ്പോഴും അതിന്റെ ടാസ്കുകൾ എണ്ണും, "A members-only project" എന്ന് കാണിച്ച്. അനുമതിക്കോ സൈൻ-ഓഫിനോ നിങ്ങൾ ആവശ്യപ്പെടുന്ന ആൾ അത് തുറക്കാൻ അംഗമായിരിക്കണം. പുതിയ പ്രോജക്റ്റുകൾ Projects -> Settings -> General പറയുന്നതുപോലെ തുടങ്ങും.',
            'p5' => '**Who needs to know?** - സ്റ്റേക്ക്ഹോൾഡർ മാപ്പ്. ഒരു അംഗത്തിലെ **Place** അവരുടെ **power** (പ്രോജക്റ്റിനെ എത്രമാത്രം ബാധിക്കാം), **interest** (അത് അവരെ എത്രമാത്രം ബാധിക്കുന്നു) 1 മുതൽ 5 വരെ, അവർ എവിടെ നിൽക്കുന്നു (champion, supporter, neutral, sceptic അല്ലെങ്കിൽ blocker), അവരെ എങ്ങനെ അറിയിക്കുന്നു എന്നിവ നിശ്ചയിക്കുന്നു. മാപ്പ് ഓരോരുത്തരെയും ഒരു ക്വാഡ്രന്റിൽ ഇടുന്നു - manage closely, keep satisfied, keep informed, monitor (3-ഉം അതിനു മുകളിലും ഉയർന്നതായി കണക്കാക്കും) - അതിനു താഴെയുള്ള **communications plan** സ്ഥാനം നൽകിയ എല്ലാവരെയും ഏറ്റവും പ്രധാനപ്പെട്ടവർ ആദ്യം എന്ന ക്രമത്തിൽ പട്ടികപ്പെടുത്തുന്നു. ബോർഡ്, സ്പോൺസർമാർ, ബാധിക്കപ്പെടുന്നവർ എന്നിവരെ അംഗങ്ങളായി ചേർക്കുക (People മൊഡ്യൂളിൽ നിന്നുള്ളവരും ഉൾപ്പെടെ), അവരെ സ്ഥാനപ്പെടുത്താൻ.',
        ],
        'scope' => [
            'nav' => 'Scope',
            'title' => 'Scope-ഉം MoSCoW-ഉം',
            'intro' => 'പ്രോജക്റ്റ് എന്താണ് നൽകുന്നത്, മുൻഗണന അനുസരിച്ച് തരംതിരിച്ചത്.',
            'p1' => 'Scope ടാബ് പ്രോജക്റ്റിന്റെ ഡെലിവറബിളുകളുടെയും ആവശ്യകതകളുടെയും ഒരു ബോർഡാണ്, അഞ്ച് കോളങ്ങളിൽ: Must, Should, Could, Won\'t (this time), Not prioritised. ഒരു കോളത്തിന്റെ താഴെയുള്ള ബോക്സിൽ ടൈപ്പ് ചെയ്ത് അവിടെ ഒന്ന് ചേർക്കുക, മുൻഗണന മാറ്റാൻ കാർഡ് മറ്റൊരു കോളത്തിലേക്ക് വലിച്ചിടുക - നീക്കം ചരിത്രത്തിൽ രേഖപ്പെടുത്തും.',
            'p2' => 'ഒരു കാർഡ് തുറക്കാൻ അതിൽ ക്ലിക്ക് ചെയ്യുക. തലക്കെട്ടിനും മുൻഗണനയ്ക്കും പുറമെ അതിന് ഒരു നില (Proposed, Agreed, In progress, Accepted അല്ലെങ്കിൽ Dropped), അത് ഉൾപ്പെടുന്ന ഫേസ്, ഒരു വിവരണം, **Done when...** - അത് ഡെലിവർ ചെയ്തു എന്ന് എങ്ങനെ അറിയാം - എന്നിവയുണ്ട്. ഒരു ഡെലിവറബിൾ ഇല്ലാതാക്കുന്നത് RACI മാട്രിക്സിലെ അതിന്റെ വരിയും ഇല്ലാതാക്കുന്നു.',
        ],
        'raci' => [
            'nav' => 'RACI',
            'title' => 'ആര് എന്ത് ചെയ്യുന്നു: RACI',
            'intro' => 'മുകളിൽ ആളുകൾ, വശത്ത് ഡെലിവറബിളുകൾ.',
            'p1' => 'RACI ടാബ് പ്രോജക്റ്റിലെ ആളുകളുടെ (കോളങ്ങൾ) ഡെലിവറബിളുകൾക്കെതിരായ (വരികൾ) ഒരു ഗ്രിഡാണ്, അതിനാൽ ഇതിന് രണ്ടും വേണം: ആദ്യം People ടാബിൽ ആളുകളെയും Scope ടാബിൽ ഡെലിവറബിളുകളെയും ചേർക്കുക. Dropped ആയ ഡെലിവറബിളുകൾ ഒഴിവാക്കപ്പെടും.',
            'p2' => 'ഒരു സെല്ലിൽ ക്ലിക്ക് ചെയ്താൽ അത് R, A, C, I എന്നിവയിലൂടെ കടന്ന് വീണ്ടും ശൂന്യമാകും. ഓരോ ഡെലിവറബിളിനും ഒരാൾ accountable ആയിരിക്കും: രണ്ടാമതൊരാൾക്ക് A നൽകിയാൽ മുമ്പത്തെയാൾ Responsible ആകും, കാരണം അവർ ഇപ്പോഴും ജോലി ചെയ്യുന്നുണ്ട്. ആരും accountable അല്ലാത്തതോ ആരും responsible അല്ലാത്തതോ ആയ വരി ഡ്രാഫ്റ്റ് ചെയ്യുമ്പോൾ അനുവദനീയമാണ്, ഡെലിവറബിളിന്റെ പേരിനു താഴെ അടയാളപ്പെടുത്തും.',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'RAID ലോഗും ഹീറ്റ് മാപ്പും',
            'intro' => 'എന്ത് തെറ്റിപ്പോകാം, നിങ്ങൾ എന്ത് അനുമാനിക്കുന്നു, എന്ത് തെറ്റിപ്പോയി, എന്തിനായി കാത്തിരിക്കുന്നു, എന്ത് തീരുമാനിച്ചു.',
            'p1' => 'RAID ടാബ് ആറ് തരം എൻട്രികൾ രേഖപ്പെടുത്തുന്നു: റിസ്കുകൾ, അനുമാനങ്ങൾ, ഇഷ്യൂകൾ, ഡിപ്പൻഡൻസികൾ, തീരുമാനങ്ങൾ, പാഠങ്ങൾ. ഓരോന്നിനും തലക്കെട്ട്, വിശദാംശം, ഉടമ, അവലോകന തീയതി, നില (Open അല്ലെങ്കിൽ Closed) എന്നിവയുണ്ട്. മുകളിലെ ബട്ടണുകൾ തരം അനുസരിച്ച് ഫിൽട്ടർ ചെയ്യുകയും ഓരോന്നിലും എത്രയെണ്ണം തുറന്നിരിക്കുന്നു എന്ന് കാണിക്കുകയും ചെയ്യുന്നു; **അടച്ചവ കാണിക്കുക** അടച്ച എൻട്രികളെ ലിസ്റ്റിലേക്ക് തിരികെ കൊണ്ടുവരുന്നു. ഒരു എൻട്രി രേഖപ്പെടുത്തൽ, അടയ്ക്കൽ, വീണ്ടും തുറക്കൽ, ഇല്ലാതാക്കൽ എന്നിവയെല്ലാം ചരിത്രത്തിൽ രേഖപ്പെടുത്തും.',
            'p2' => 'ഒരു റിസ്കിന് സാധ്യതയും ആഘാതവും ഉണ്ട്, രണ്ടും അഞ്ച് തട്ടുകളുള്ള സ്കെയിലിൽ, കൂടാതെ സാധ്യതയും ആഘാതവും ഗുണിച്ചുള്ള **സ്കോർ** 1 മുതൽ 25 വരെ. അതിന് ഒരു പ്രതികരണവും (Avoid, Reduce, Transfer, Accept അല്ലെങ്കിൽ Share) അത് എങ്ങനെ കൈകാര്യം ചെയ്യുമെന്നതിനുള്ള പദ്ധതിയും ഉണ്ടാകാം. ഒരു ഇഷ്യൂവിന് ആഘാതമുണ്ട്, അതിനെ ഒരു ടിക്കറ്റുമായി ലിങ്ക് ചെയ്യാം, ആ ടിക്കറ്റ് നിങ്ങൾക്ക് തുറക്കാൻ കഴിയുകയും അത് പ്രോജക്റ്റിന്റെ കമ്പനിയുടേതായിരിക്കുകയും വേണം.',
            'p3' => 'ഹീറ്റ് മാപ്പ്, **എന്ത് തെറ്റിപ്പോകാം?**, സാധ്യതയും ആഘാതവും ഉള്ള എല്ലാ തുറന്ന റിസ്കുകളെയും അഞ്ച്-ബൈ-അഞ്ച് ഗ്രിഡിൽ സ്കോർ അനുസരിച്ച് പച്ച മുതൽ ചുവപ്പ് വരെ നിറം നൽകി സ്ഥാപിക്കുന്നു. ആ റിസ്കുകൾ മാത്രം ലിസ്റ്റ് ചെയ്യാൻ ഒരു ചതുരത്തിൽ ക്ലിക്ക് ചെയ്യുക; മായ്ക്കാൻ വീണ്ടും ക്ലിക്ക് ചെയ്യുക, അല്ലെങ്കിൽ **എല്ലാം കാണിക്കുക** അമർത്തുക. രണ്ട് സ്കെയിലുകളിലെയും വാക്കുകൾ **Projects - Settings - RAID** എന്നതിൽ നിന്നാണ് വരുന്നത്.',
            'p5' => 'ഒരു **ഡിപ്പൻഡൻസി** എന്നത് പ്രോജക്റ്റിന് പുറത്തുനിന്ന് അതിന് ആവശ്യമായ ഒന്നാണ് - ഫിറ്റ്-ഔട്ട് പൂർത്തിയാക്കുന്ന കെട്ടിട ഉടമ, ഒരു സപ്ലയർ ഡെലിവർ ചെയ്യുന്നത്, മറ്റൊരു ടീം. അതിന്റെ തീയതി അത് എപ്പോഴത്തേക്ക് വേണം എന്നതാണ്; അത് എത്തുമ്പോൾ അടയ്ക്കുക. ഒരു **തീരുമാനം** എടുക്കുന്നതിന് മുമ്പേ രേഖപ്പെടുത്തുന്നു, അത് എടുക്കേണ്ട തീയതിയോടെ, എടുക്കുമ്പോൾ **തീരുമാനിച്ചത്** (ഏത് പേരും - സ്പോൺസർ, ബോർഡ്), **തീരുമാനിച്ച തീയതി**, **എന്തുകൊണ്ട്** എന്നിവയോടെ അടയ്ക്കുന്നു. തീരുമാന ലോഗ് ആയി കാണാൻ **തീരുമാനങ്ങൾ** തിരഞ്ഞെടുക്കുക. തീയതി കഴിഞ്ഞിട്ടും തുറന്നിരിക്കുന്ന ഒരു ഡിപ്പൻഡൻസിയോ തീരുമാനമോ പ്രോജക്റ്റിനെ ആംബർ ആക്കും.',
            'p6' => 'ഒരു സേവ് ചെയ്ത എൻട്രി തുറന്ന് അത് **എസ്കലേറ്റ്** ചെയ്യുക - പ്രോജക്റ്റ് മാനേജർക്ക് മുകളിലുള്ള ഒരാൾ ആവശ്യമുള്ളപ്പോൾ - എന്താണ് വേണ്ടതെന്ന് പറയുന്ന ഒരു വരിയോടെ. **ഡി-എസ്കലേറ്റ്** ചെയ്യുകയോ അടയ്ക്കുകയോ ചെയ്യുന്നതുവരെ ഇത് ഓവർവ്യൂവിലും RAID ടാബിലും പോർട്ട്ഫോളിയോ കാർഡിലും അടയാളപ്പെടുത്തി കാണിക്കും; പ്രോജക്റ്റ് മാനേജരെ അറിയിക്കും, ഒരു വർക്ക്ഫ്ലോയ്ക്ക് സ്പോൺസറെ അറിയിക്കാനും കഴിയും. **തുടർനടപടികൾ** എൻട്രിയിൽ നിന്ന് ഉണ്ടാക്കുന്ന പ്രോജക്റ്റിലെ ടാസ്കുകളാണ് - ഒരു തീരുമാനത്തിന് ശേഷം സമ്മതിച്ചത്, ഒരു റിസ്കിനുള്ള ലഘൂകരണം - എത്രയെണ്ണം പൂർത്തിയായി എന്ന് ലോഗിൽ കാണിക്കും.',
            'p4' => 'ഒരു സേവ് ചെയ്ത **പാഠം** തുറന്ന് **Knowledge** അമർത്തിയാൽ അത് ഒരു ഡ്രാഫ്റ്റ് Knowledge ലേഖനമായി മാറും: അതിന്റെ വിശദാംശം ലേഖനമാകുന്നു, പ്രോജക്റ്റിലേക്കുള്ള ലിങ്കോടെ, അത് Connections ടാബിൽ ലിങ്ക് ചെയ്യപ്പെടുന്നു. Knowledge-ൽ വായിച്ച ശേഷം പ്രസിദ്ധീകരിക്കുക. ഒരു സേവ് ചെയ്ത **ഇഷ്യൂ** തുറന്ന് **Raise** അമർത്തിയാൽ, ഇതിനകം ഉള്ള ഒന്ന് ലിങ്ക് ചെയ്യുന്നതിന് പകരം അതിൽ നിന്ന് ഒരു പുതിയ ടിക്കറ്റ് ഉണ്ടാക്കാം: നിങ്ങളാണ് അഭ്യർത്ഥിച്ചയാൾ, അത് ഇഷ്യൂവിന്റെ ഉടമയ്ക്ക് (അല്ലെങ്കിൽ നിങ്ങൾക്ക്) പോകുന്നു, അത് പ്രോജക്റ്റിന്റെ കമ്പനിയുടേതാണ്, ഇഷ്യൂവും പ്രോജക്റ്റും രണ്ടും അതിലേക്ക് ലിങ്ക് ചെയ്യുന്നു. ഓരോന്നും ഒരു എൻട്രിക്ക് ഒരിക്കൽ മാത്രമേ ചെയ്യാനാകൂ, പ്രോജക്റ്റ് മാറ്റാൻ അനുവാദം ഉള്ളതിനൊപ്പം Knowledge അല്ലെങ്കിൽ Tickets-ലേക്കുള്ള ആക്സസും ആവശ്യമാണ്.',
            'p7' => '**എക്സ്പോർട്ട്** (അടച്ചവ കാണിക്കുക എന്നതിന് അടുത്ത്) മുഴുവൻ ലോഗും - എല്ലാ തരവും, തുറന്നതും അടച്ചതും - ഉടമകൾ, സ്കോറുകൾ, പ്രതികരണങ്ങൾ, തീരുമാനങ്ങൾ, തുടർനടപടികൾ എന്നിവയോടെ ഒരു Excel വർക്ക്ബുക്കായോ CSV ഫയലായോ ഡൗൺലോഡ് ചെയ്യുന്നു.',
        ],
        'gates' => [
            'nav' => 'ഗേറ്റുകൾ',
            'title' => 'ഗേറ്റുകൾ, ടോളറൻസുകൾ, എക്സെപ്ഷനുകൾ',
            'intro' => 'ഘട്ടങ്ങളായി നടത്തുന്ന ഒരു പ്രോജക്റ്റ് ഉത്തരം പറയേണ്ട നിയന്ത്രണങ്ങൾ, PRINCE2 ശൈലിയിൽ.',
            'p1' => 'ഗേറ്റ്സ് ടാബിൽ മൂന്ന് കാര്യങ്ങളുണ്ട്. **ബിസിനസ് കേസ്** പ്രോജക്റ്റ് ചെയ്യുന്നത് എന്തുകൊണ്ട് മൂല്യമുള്ളതാണെന്ന് പറയുന്നു - ആനുകൂല്യങ്ങൾ, ചെലവുകൾ, റിസ്കുകൾ - ഓരോ ഗേറ്റിലും അവലോകനം ചെയ്യാനുള്ളതാണ് ഇത്. **ടോളറൻസുകൾ** ഒരു തീരുമാനം ആവശ്യമാകുന്നതിന് മുമ്പ് പ്രോജക്റ്റിന് എത്ര വ്യതിചലിക്കാമെന്ന് പറയുന്നു. **ഘട്ട ഗേറ്റുകൾ** ഓരോ ഘട്ടത്തിന്റെയും അവസാനം ഒരു തീരുമാനം രേഖപ്പെടുത്തുന്നു.',
            'p2' => 'രണ്ട് ടോളറൻസുകളുണ്ട്, ഒന്ന് ശൂന്യമാക്കിയാൽ അത് ഓഫ് ആകും. ജോലി ഇപ്പോഴും തുറന്നിരിക്കെ ലക്ഷ്യ പൂർത്തീകരണ തീയതിയോ നടക്കുന്ന ഘട്ടത്തിന്റെ അവസാന തീയതിയോ അത്രയും ദിവസത്തിലധികം കഴിഞ്ഞുപോയാൽ **അനുവദിച്ച വൈകൽ ദിവസങ്ങൾ** മറികടക്കുന്നു. RAID ലോഗിലെ ഒരു തുറന്ന റിസ്കിന്റെ സ്കോർ അതിനേക്കാൾ കൂടിയാൽ **അനുവദിച്ച ഏറ്റവും ഉയർന്ന റിസ്ക് സ്കോർ** മറികടക്കുന്നു.',
            'p3' => 'ഒരു ടോളറൻസ് കടന്നുപോയാൽ പ്രോജക്റ്റ് ഒരു **എക്സെപ്ഷൻ** ആകുന്നു. അത് നിലനിൽക്കുന്നിടത്തോളം, കണക്കാക്കിയ ഹെൽത്ത് Off track ആയിരിക്കും, **ടോളറൻസ് മറികടന്നു** എന്ന ബാനർ ഓവർവ്യൂവിലും ഗേറ്റ്സ് ടാബിലും ഓരോന്നിനെയും പേരെടുത്ത് പറയും, പോർട്ട്ഫോളിയോയിലെ പ്രോജക്റ്റിന്റെ കാർഡിൽ **എക്സെപ്ഷൻ** ചിപ്പ് ഉണ്ടാകും. പ്രോജക്റ്റ് കാണിക്കുമ്പോഴെല്ലാം എക്സെപ്ഷനുകൾ കണക്കാക്കുന്നു, ഒരിക്കലും സംഭരിക്കുന്നില്ല, അതിനാൽ പ്രോജക്റ്റ് വീണ്ടും ടോളറൻസുകൾക്കുള്ളിൽ വന്നാൽ അവ സ്വയം ഇല്ലാതാകും. ഗേറ്റ്സ് ടൂൾ ഓൺ ആക്കിയ ലൈവ് പ്രോജക്റ്റിന് മാത്രമേ ഇവ ബാധകമാകൂ, കൈകൊണ്ട് സജ്ജമാക്കിയ ഹെൽത്ത് സജ്ജമാക്കിയതുപോലെ തന്നെ തുടരും.',
            'p4' => 'നടക്കുന്നതോ പൂർത്തിയായതോ ആയ ഒരു ഘട്ടത്തിൽ **തീരുമാനിക്കുക** അമർത്തുക (ആസൂത്രണം ചെയ്ത ഘട്ടത്തിന് ബട്ടൺ ഇല്ല), ഒരു തീരുമാനം തിരഞ്ഞെടുത്ത് കുറിപ്പുകൾ ചേർക്കുക. തീരുമാനം, ആര് എടുത്തു, എപ്പോൾ എന്നിവ ഘട്ടത്തിൽ തുടരും, അത് ചരിത്രത്തിൽ രേഖപ്പെടുത്തുകയും ചെയ്യും. ഇതിനകം പൂർത്തിയായ ഘട്ടത്തിൽ രേഖപ്പെടുത്തിയ ഗോ തീരുമാനം മാത്രമേ രേഖപ്പെടുത്തൂ: മറ്റൊരു ഘട്ടം ആരംഭിക്കില്ല.',
            'p5' => 'ഒരു തീരുമാനത്തിന് മുമ്പ്, ഗേറ്റ് Connections ടാബിൽ ലിങ്ക് ചെയ്ത **മാറ്റങ്ങൾ** പരിശോധിക്കുന്നു. ഇപ്പോഴും തുറന്നതും അനുമതി ലഭിക്കാത്തതുമായവ - അനുമതിക്കായി കാത്തിരിക്കുന്നത്, അല്ലെങ്കിൽ ആരും സമർപ്പിക്കാത്ത ഒരു ഡ്രാഫ്റ്റ് - അവയുടെ നിലയും ആസൂത്രിത ആരംഭവും സഹിതം ഗേറ്റ് ഡയലോഗിൽ ലിസ്റ്റ് ചെയ്യും, നടക്കുന്ന ഘട്ടത്തിൽ എത്രയെണ്ണമെന്ന് പറയുന്ന ഒരു ചിപ്പ് ഉണ്ടാകും. ഇത് ഒരു മുന്നറിയിപ്പാണ്, തടസ്സമല്ല: തീരുമാനം ഇപ്പോഴും നിങ്ങളുടേതാണ്. Changes തുറക്കാൻ കഴിയുമെങ്കിൽ മാത്രമേ ഇത് കാണൂ.',
            'p6' => 'ഓരോ ഗേറ്റിനും ഒരു ഗോയ്ക്ക് മുമ്പ് ശരിയായിരിക്കേണ്ടവയുടെ **ചെക്ക്‌ലിസ്റ്റ്** ഉണ്ടാകാം: ടിക്ക് ചെയ്യാനുള്ള ഒരു **ചെക്ക്**; ഒരു **പ്രമാണം** - പ്രോജക്റ്റിന്റെ **Documents** ടാബിലെ ഫയലുകളിലൊന്ന് തിരഞ്ഞെടുത്ത് ചെയ്യുന്നത് (ബാക്ക്ഔട്ട് പ്ലാൻ, ടെസ്റ്റ് റിപ്പോർട്ട്); പേര് നൽകിയ ഒരു വ്യക്തിയുടെ **സൈൻ-ഓഫ്**, അദ്ദേഹത്തെ ബെല്ലിൽ അറിയിക്കും, അത് ഒപ്പിടാൻ കഴിയുന്ന ഏക വ്യക്തിയും അദ്ദേഹമാണ്; അല്ലെങ്കിൽ Changes-ൽ അനുമതി ലഭിക്കേണ്ട ഒരു ലിങ്ക് ചെയ്ത **മാറ്റം**. ഒരു ഗേറ്റിനെ **ഗോ-ലൈവ് ഗേറ്റ്** ആക്കിയാൽ അതിന് ഒരു സ്റ്റാർട്ടർ ചെക്ക്‌ലിസ്റ്റ് ലഭിക്കും - യൂസർ അക്സപ്റ്റൻസ് ടെസ്റ്റിംഗ് സൈൻ-ഓഫ്, ഒരു ബാക്ക്ഔട്ട് പ്ലാൻ, മാറ്റത്തിന് അനുമതി, സപ്പോർട്ട് ഹാൻഡ്ഓവർ സമ്മതിക്കൽ - നിലനിർത്താനോ മാറ്റാനോ ചേർക്കാനോ. എല്ലാ ഇനങ്ങളും പൂർത്തിയാകുന്നതുവരെ ഒരു ഗോ നിരസിക്കപ്പെടും (സ്റ്റോപ്പ് ഒരിക്കലും നിരസിക്കപ്പെടില്ല); Projects - Settings - General ഇതിനെ ഒരു മുന്നറിയിപ്പാക്കി മാറ്റാം, അപ്പോൾ ഇപ്പോഴും തുറന്നിരുന്നവ ഗേറ്റിന്റെ കുറിപ്പുകളിൽ എഴുതപ്പെടും.',
            'go_d' => 'ഘട്ടം അടയ്ക്കുകയും ആസൂത്രണം ചെയ്ത അടുത്തത് ആരംഭിക്കുകയും ചെയ്യുന്നു.',
            'go_with_conditions_d' => 'ഗോ പോലെ തന്നെ, നിബന്ധനകൾ കുറിപ്പുകളിൽ എഴുതിയിരിക്കും - അവ നിർബന്ധമാണ്.',
            'stop_d' => 'പ്രോജക്റ്റ് ആസൂത്രണം ചെയ്തതുപോലെ തുടരരുത് എന്ന് രേഖപ്പെടുത്തുന്നു. ഇത് ഒരു ഘട്ടവും മാറ്റുന്നില്ല: അടുത്തതായി എന്ത് സംഭവിക്കണമെന്ന് പ്രോജക്റ്റ് നടത്തുന്നവർ തീരുമാനിക്കണം.',
        ],
        'templates' => [
            'nav' => 'ടെംപ്ലേറ്റുകൾ',
            'title' => 'ഒരു ടെംപ്ലേറ്റിൽ നിന്ന് തുടങ്ങുക',
            'intro' => 'ആസൂത്രണം ചെയ്തുകഴിഞ്ഞ നിലയിൽ എത്തുന്ന ഒരു പ്രോജക്റ്റ്.',
            'p1' => 'ഒരു പ്രോജക്റ്റ് സൃഷ്ടിക്കുമ്പോൾ, **ഇതിൽ നിന്ന് തുടങ്ങുക** ടെംപ്ലേറ്റുകൾ നൽകുന്നു: ഓഫീസ് മാറ്റം, ലാപ്ടോപ്പ് റിഫ്രഷ്, മെയിൽ മൈഗ്രേഷൻ, Windows 11 റോൾഔട്ട്, സർവീസ് ഡെസ്ക് മെച്ചപ്പെടുത്തൽ എന്നിവ ബിൽറ്റ്-ഇൻ ആയി വരുന്നു. ഒന്ന് തിരഞ്ഞെടുത്താൽ പ്രോജക്റ്റ് അതിന്റെ ഘട്ടങ്ങൾ, ടാസ്കുകൾ, സ്കോപ്പ്, റിസ്കുകൾ, ടോളറൻസുകൾ എന്നിവ ഇതിനകം ഉൾപ്പെടുത്തി സൃഷ്ടിക്കപ്പെടും, അതിന്റെ പ്രവർത്തന രീതി, നിറം, ഐക്കൺ, ലക്ഷ്യം എന്നിവയും നിങ്ങൾക്കായി പൂരിപ്പിക്കപ്പെടും. ഫോമിൽ നിങ്ങൾ ടൈപ്പ് ചെയ്യുന്നതെന്തും ടെംപ്ലേറ്റിനേക്കാൾ മുൻഗണന നേടും.',
            'p2' => 'ഒരു ടെംപ്ലേറ്റ് അതിന്റെ തീയതികൾ ആരംഭം മുതലുള്ള ദിവസങ്ങളായി സൂക്ഷിക്കുന്നു, അതിനാൽ നിങ്ങൾ നൽകുന്ന **ആരംഭ തീയതി** മുതൽ ഓരോ തീയതിയും ആസൂത്രണം ചെയ്യപ്പെടും - ശൂന്യമാക്കിയാൽ ഇന്ന് - നിങ്ങൾ ഒന്ന് സജ്ജമാക്കിയില്ലെങ്കിൽ ലക്ഷ്യ പൂർത്തീകരണ തീയതി പിന്തുടരും. ടാസ്കുകൾ സാധാരണ ടാസ്കുകളാണ്, ആരെയും നിയോഗിച്ചിട്ടില്ല, ഒന്നും ടിക്ക് ചെയ്തിട്ടില്ല. പേര് അനുസരിച്ച് ഒരു നിലയോ സ്ഥലമോ ആവശ്യമുള്ള ആസ്തി ടാർഗെറ്റ് ("Retired" പോലെ) ആ പേര് നിങ്ങളുടെ ഇൻസ്റ്റലേഷനിൽ ഉണ്ടെങ്കിൽ മാത്രം ചേർക്കപ്പെടും.',
            'p3' => 'സ്വന്തമായി ഉണ്ടാക്കാൻ, നന്നായി നടന്ന ഒരു പ്രോജക്റ്റ് തുറന്ന് **ടെംപ്ലേറ്റ്** അമർത്തുക. എന്ത് സൂക്ഷിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക: ഘട്ടങ്ങളും ടാസ്കുകളും, സ്കോപ്പ്, റിസ്കുകളും അനുമാനങ്ങളും, ടോളറൻസുകൾ (അനുവദിച്ച അധിക ചെലവ് ഉൾപ്പെടെ), ആസ്തി ടാർഗെറ്റുകൾ. ഒരു ടെംപ്ലേറ്റ് മാറ്റാൻ, അതിൽ നിന്ന് ഒരു പ്രോജക്റ്റ് തുടങ്ങി, പ്രോജക്റ്റ് മാറ്റി, **ടെംപ്ലേറ്റ്** അമർത്തി **നിങ്ങളുടെ ടെംപ്ലേറ്റുകളിൽ ഒന്ന് മാറ്റിസ്ഥാപിക്കുക** തിരഞ്ഞെടുക്കുക - ബിൽറ്റ്-ഇൻ ടെംപ്ലേറ്റുകൾ ഇങ്ങനെ പകർത്താം, ഒരിക്കലും മാറ്റിയെഴുതാനാവില്ല. ആളുകൾ, കമ്പനി, ലിങ്കുകൾ, പുരോഗതി എന്നിവ ഒരിക്കലും സൂക്ഷിക്കില്ല, അതിനാൽ ഒരു ടെംപ്ലേറ്റ് ഏത് കമ്പനിക്കും പ്രവർത്തിക്കും. **Projects - Settings - Templates** എല്ലാറ്റിനെയും ലിസ്റ്റ് ചെയ്യുന്നു: നിങ്ങൾ ഒരിക്കലും ഉപയോഗിക്കാത്ത ബിൽറ്റ്-ഇൻ ഒന്നിനെ മറയ്ക്കുക, സ്വന്തമായവയുടെ പേര് മാറ്റുക, ഓഫ് ആക്കുക അല്ലെങ്കിൽ ഇല്ലാതാക്കുക. ടെംപ്ലേറ്റുകൾ സേവ് ചെയ്യാനും പരിപാലിക്കാനും Templates അനുമതി ആവശ്യമാണ്; പ്രോജക്റ്റുകൾ സൃഷ്ടിക്കാൻ അനുവാദമുള്ള ആർക്കും ഒന്നിൽ നിന്ന് തുടങ്ങാം.',
            'p4' => '3.3.0 മുതൽ ഒരു ടെംപ്ലേറ്റ് പ്ലാനിന്റെ **ഡിപ്പൻഡൻസികൾ**, ഓരോ ഘട്ടത്തിന്റെയും **ഗേറ്റ് ചെക്ക്‌ലിസ്റ്റ്** (അത് ഒരു ഗോ-ലൈവ് ഗേറ്റ് ആണോ എന്നതും - സൈൻ-ഓഫിന് ഇതുവരെ ആരുടെയും പേര് നൽകിയിട്ടില്ലാതെ), നിങ്ങൾ സൂക്ഷിക്കുന്നെങ്കിൽ **ആനുകൂല്യങ്ങൾ** അവയുടെ ടാർഗെറ്റുകളോടെ (ബേസ്‌ലൈനുകൾ ഒരിക്കലുമില്ല - അവ പുതിയ പ്രോജക്റ്റിൽ അളക്കുന്നവയാണ്) കൂടി വഹിക്കുന്നു. അഞ്ച് ബിൽറ്റ്-ഇൻ ടെംപ്ലേറ്റുകളിലും ഈ മൂന്നും ഉണ്ട്.',
        ],
        'targets' => [
            'nav' => 'ആസ്തി ടാർഗെറ്റുകൾ',
            'title' => 'ആസ്തി ടാർഗെറ്റുകൾ: Assets-ൽ നിന്ന് നേരിട്ടുള്ള പുരോഗതി',
            'intro' => '"480 ലാപ്ടോപ്പുകളിൽ 312 എണ്ണം മാറ്റി", ആസ്തികളിൽ നിന്ന് തന്നെ എണ്ണിയത്.',
            'p1' => 'ഒരു ആസ്തി ടാർഗെറ്റ് പ്രോജക്റ്റിന്റെ ഓവർവ്യൂവിൽ ഇരുന്ന് Assets-ലെ എന്തെങ്കിലും എണ്ണുന്നു: റിട്ടയർ ചെയ്ത Latitude 5430-കൾ, ഇപ്പോൾ Windows 11-ൽ ഉള്ള Windows മെഷീനുകൾ, BitLocker ഓൺ ആയ ലാപ്ടോപ്പുകൾ. പേജ് തുറക്കുമ്പോഴെല്ലാം എണ്ണം കണക്കാക്കുന്നു, അതിനാൽ ആരെങ്കിലും ഒരു ആസ്തി മാറ്റുന്ന നിമിഷം പ്രോജക്റ്റ് നീങ്ങും - ഒന്നും ടിക്ക് ചെയ്യാൻ ആരും ഓർക്കേണ്ടതില്ല. ഓരോ ടാർഗെറ്റും അത് സജ്ജമാക്കിയ ദിവസം മുതൽ ദിവസവും ഒരു പോയിന്റ് വീതം, അതിന്റെ പുരോഗതിയുടെ ഒരു വര വരയ്ക്കുന്നു.',
            'p2' => '**ഏത് ആസ്തികൾ** എന്ന് തിരഞ്ഞെടുക്കുക: ഒരു തരവും കൂടാതെ/അല്ലെങ്കിൽ ചില ടെക്സ്റ്റ് അടങ്ങിയ ഒരു ഫീൽഡും **പൊരുത്തപ്പെടുന്നവ** (മോഡലിൽ 5430 അടങ്ങിയിരിക്കുന്നു), അല്ലെങ്കിൽ Connections ടാബിൽ **ഈ പ്രോജക്റ്റിലേക്ക് ലിങ്ക് ചെയ്തവ**. പിന്നെ **ഒന്ന് എപ്പോൾ പൂർത്തിയായതായി കണക്കാക്കും** എന്ന് തിരഞ്ഞെടുക്കുക: ഒരു നില, ഒരു സ്ഥലം, ഓപ്പറേറ്റിംഗ് സിസ്റ്റം, ഫീച്ചർ റിലീസ്, മോഡൽ, നിർമ്മാതാവ്, BitLocker അല്ലെങ്കിൽ TPM പതിപ്പ്. നിങ്ങൾ ടൈപ്പ് ചെയ്യുമ്പോൾ എത്ര ആസ്തികൾ പൊരുത്തപ്പെടുന്നു, എത്ര എണ്ണം പൂർത്തിയായി എന്ന് ഡയലോഗ് കാണിക്കും. ഒരു ടാർഗെറ്റ് പ്രോജക്റ്റിന്റെ സ്വന്തം കമ്പനിയിലെ ആസ്തികളെ മാത്രമേ എണ്ണൂ.',
            'p3' => 'ഓരോ ടാർഗെറ്റിനും ഒരു തീയതിയുണ്ട് - അതിന്റെ സ്വന്തമോ പ്രോജക്റ്റിന്റെ ലക്ഷ്യ അവസാന തീയതിയോ. തീയതി കഴിഞ്ഞിട്ടും പൂർത്തിയാകാത്ത ടാർഗെറ്റ് പ്രോജക്റ്റിനെ ചുവപ്പാക്കുന്നു; സജ്ജമാക്കിയ ദിവസം മുതൽ അതിന്റെ തീയതി വരെയുള്ള നേർരേഖയിൽ നിന്ന് 25 പോയിന്റിൽ കൂടുതൽ പിന്നിലായ ഒന്ന് അതിനെ ആംബർ ആക്കുന്നു. **ഇനിയും ചെയ്യാനുള്ളവ** ബാക്കിയുള്ള ആസ്തികളെ ലിസ്റ്റ് ചെയ്യുന്നു, ഓരോന്നും ആസ്തിയിലേക്കുള്ള ലിങ്ക്. ഒരു ടാർഗെറ്റ് സജ്ജമാക്കാനും അതിന് പിന്നിൽ ഏത് ആസ്തികളാണെന്ന് കാണാനും പ്രോജക്റ്റ് മാറ്റാൻ അനുവാദം ഉള്ളതിനൊപ്പം Assets-ലേക്കുള്ള ആക്സസും ആവശ്യമാണ്; നിയമം മാറ്റിയാൽ അതിന്റെ വര വീണ്ടും തുടങ്ങും.',
        ],
        'health' => [
            'nav' => 'ഹെൽത്ത്',
            'title' => 'ഹെൽത്ത് എങ്ങനെ കണക്കാക്കുന്നു',
            'intro' => 'പ്ലാനിൽ നിന്ന്, ആരുടെയും മനോഭാവത്തിൽ നിന്നല്ല.',
            'p1' => 'ആരെങ്കിലും കൈകൊണ്ട് സജ്ജമാക്കിയില്ലെങ്കിൽ, ഒരു ലൈവ് പ്രോജക്റ്റിന്റെ ഹെൽത്ത് കാണിക്കുമ്പോഴെല്ലാം അതിന്റെ ടാസ്കുകളിൽ നിന്നും ലക്ഷ്യ തീയതിയിൽ നിന്നും കണക്കാക്കുന്നു. താഴെയുള്ള കണക്കുകൾ സ്ഥിരസ്ഥിതിയാണ്; അവ **Projects - Settings - Health** എന്നതിൽ മാറ്റാം.',
            'green_d' => 'താഴെയുള്ള ഒന്നും ബാധകമല്ല.',
            'amber_d' => 'കുറഞ്ഞത് ഒരു തുറന്ന ടാസ്ക് കാലാവധി കഴിഞ്ഞിരിക്കുന്നു, ഒരു മൈൽസ്റ്റോൺ നഷ്ടമായി, അല്ലെങ്കിൽ ഒരു ഡിപ്പൻഡൻസിയോ തീരുമാനമോ അതിന്റെ തീയതി കഴിഞ്ഞിരിക്കുന്നു (ഇവ രണ്ടും ചുവപ്പാക്കാനോ ഒന്നും ചെയ്യാതിരിക്കാനോ Projects - Settings - Health-ൽ സജ്ജമാക്കാം), ലക്ഷ്യ തീയതി അടുത്തിരിക്കുകയും വളരെ കുറച്ച് ജോലി മാത്രം പൂർത്തിയാകുകയും ചെയ്തു - സ്ഥിരസ്ഥിതിയായി 14 ദിവസത്തിനുള്ളിൽ നാലിൽ മൂന്ന് ഭാഗത്തിൽ താഴെ പൂർത്തിയായി - അല്ലെങ്കിൽ ലിങ്ക് ചെയ്ത ടിക്കറ്റുകളിൽ ഒരു കുതിച്ചുചാട്ടം: സ്ഥിരസ്ഥിതിയായി കഴിഞ്ഞ 7 ദിവസത്തിൽ 5 ഓ അതിലധികമോ ഉണ്ടായാൽ, ഗോ-ലൈവിന് ശേഷം ഇത് സാധാരണയായി എന്തെങ്കിലും ശരിയാക്കണം എന്നാണ് അർത്ഥമാക്കുന്നത്.',
            'red_d' => 'ജോലി ഇപ്പോഴും തുറന്നിരിക്കെ ലക്ഷ്യ തീയതി കഴിഞ്ഞു, തുറന്ന ജോലിയുടെ വളരെയധികം ഭാഗം കാലാവധി കഴിഞ്ഞു - സ്ഥിരസ്ഥിതിയായി നാലിലൊന്നോ അതിൽ കൂടുതലോ - അല്ലെങ്കിൽ പ്രോജക്റ്റ് അതിന്റെ ടോളറൻസുകളിലൊന്ന് കടന്നുപോയി (ഗേറ്റുകൾ കാണുക). ആസ്തി ടാർഗെറ്റുകളും കണക്കിലെടുക്കുന്നു: തീയതി കഴിഞ്ഞ ഒന്ന് പ്രോജക്റ്റിനെ ചുവപ്പാക്കുന്നു, വളരെ പിന്നിലായ ഒന്ന് പച്ച പ്രോജക്റ്റിനെ ആംബർ ആക്കുന്നു (ആസ്തി ടാർഗെറ്റുകൾ കാണുക).',
            'p2' => 'സ്വയം സജ്ജമാക്കാൻ, പ്രോജക്റ്റ് എഡിറ്റ് ചെയ്ത് ഒരു ഹെൽത്ത് തിരഞ്ഞെടുക്കുക; എന്തുകൊണ്ടെന്ന് പറയുന്ന ഒരു വരി ചേർക്കുക. തിരികെ ഏൽപ്പിക്കാൻ **എനിക്കായി കണക്കാക്കുക** തിരഞ്ഞെടുക്കുക. അടച്ചതും റദ്ദാക്കിയതുമായ പ്രോജക്റ്റുകൾക്ക് ഹെൽത്ത് ഇല്ല.',
        ],
        'tasks' => [
            'nav' => 'ടാസ്കുകൾ',
            'title' => 'പ്രോജക്റ്റ് ടാസ്കുകൾ സാധാരണ ടാസ്കുകളാണ്',
            'intro' => 'ഒരാൾക്ക് ഒരു ജോലിപ്പട്ടിക, രണ്ടല്ല.',
            'p1' => 'ഒരു പ്രോജക്റ്റിൽ ചേർത്ത ടാസ്ക് ഒരു സാധാരണ ടാസ്കാണ്: അത് Tasks ബോർഡിൽ കാണിക്കും, അത് നിയോഗിക്കാം, ഷെഡ്യൂൾ ചെയ്യാം, സമയം കണക്കാക്കാം, അഭിപ്രായം ഇടാം, ഉപടാസ്കുകളും ചെക്ക്‌ലിസ്റ്റുകളും നൽകാം, പതിവ് ഇമെയിലുകളും അറിയിപ്പുകളും അയയ്ക്കും. പുരോഗതി ഉയർന്ന തലത്തിലെ ടാസ്കുകളെ എണ്ണുന്നു; ഉപടാസ്കുകൾ അവയുടെ ടാസ്കിന്റേതാണ്.',
            'p2' => 'ഒരു പ്രോജക്റ്റ് ഇല്ലാതാക്കുന്നത് അതിന്റെ ടാസ്കുകളെ ഒരിക്കലും ഇല്ലാതാക്കില്ല. അവ Tasks ബോർഡിൽ തുടരും, ഒരു പ്രോജക്റ്റിന്റേതല്ലാതാകുക മാത്രം ചെയ്യും. ഒരു ഫേസ് നീക്കം ചെയ്യുന്നതും ഇതുപോലെ തന്നെ: അതിന്റെ ടാസ്കുകൾ പ്രോജക്റ്റിൽ തുടരും, ഒരു ഫേസിൽ ഇല്ലാതെ മാത്രം.',
        ],
        'contractors' => [
            'nav' => 'കോൺട്രാക്ടർമാർ',
            'title' => 'കോൺട്രാക്ടർമാർ ചെയ്യുന്ന ജോലി',
            'intro' => 'ഒരു പുറം സ്ഥാപനം പ്രോജക്റ്റിന്റെ ഒരു ഭാഗം ചെയ്യുമ്പോൾ - കേബിളിംഗ്, മാറ്റം, ഇൻസ്റ്റാൾ.',
            'p1' => 'ഒരു ടാസ്ക് ഒരു **കോൺട്രാക്ടർക്ക്** നൽകാം: Contracts-ൽ നിന്നുള്ള ഒരു വിതരണക്കാരൻ, താൽപ്പര്യമുണ്ടെങ്കിൽ അവിടെയുള്ള ഒരു വ്യക്തിയും. Tasks ബോർഡിലെ ടാസ്ക് വിൻഡോയിൽ **കോൺട്രാക്ടർ**, **അവിടത്തെ കോൺടാക്റ്റ്** എന്നിവയ്ക്ക് കീഴിൽ അവരെ തിരഞ്ഞെടുക്കുക. **നിയോഗിച്ചയാൾ** ടാസ്കിന്റെ ഉടമയും സ്ഥാപനത്തെ പിന്തുടരുന്നയാളുമായ ഇവിടത്തെ വ്യക്തിയായി തുടരും - അതിനാൽ ഒരു കോൺട്രാക്ടർ ടാസ്കിന് രണ്ടുപേരുമുണ്ട്. ഒരു വിതരണക്കാരനെ തിരഞ്ഞെടുക്കാൻ Contracts-ലേക്കുള്ള ആക്സസ് ആവശ്യമാണ്; ടാസ്ക് കാണാൻ കഴിയുന്ന ആർക്കും അത് ആരുടെ പക്കലാണെന്ന് കാണാം.',
            'p2' => 'കോൺട്രാക്ടർ ടാസ്കുകൾ പ്ലാനിലും ടൈംലൈനിലും Tasks ബോർഡിലും സ്ഥാപനത്തിന്റെ പേര് വഹിക്കുന്നു, അവിടെ ഒരു **കോൺട്രാക്ടർ** ഫിൽട്ടർ ഒരു സ്ഥാപനത്തിന്റെ ജോലി, എല്ലാ കോൺട്രാക്ടർ ജോലിയും, അല്ലെങ്കിൽ ഒന്നുമില്ല എന്നത് കാണിക്കുന്നു. **ആളുകൾ** ടാബിൽ, **ആരെയെങ്കിലും ചേർക്കുക - കോൺട്രാക്ടർ** ഒരു സ്ഥാപനത്തെയോ അവിടെയുള്ള ഒരാളെയോ ഒരു റോളോടെ പ്രോജക്റ്റിൽ ചേർക്കുന്നു, അതുവഴി അവർക്ക് RACI മാട്രിക്സിലും സ്റ്റേക്ക്ഹോൾഡർ മാപ്പിലും ഉണ്ടാകാം. People-ലെ വിതരണക്കാരന്റെ പേജ് അവരുടെ പക്കലുള്ള എല്ലാ ടാസ്കുകളും ലിസ്റ്റ് ചെയ്യുന്നു.',
            'p3' => 'കോൺട്രാക്ടർ ജോലി **കപ്പാസിറ്റി**യിൽ ആരുടെയും ലോഡിൽ ഉൾപ്പെടുന്നില്ല - അത് താഴെ ലിസ്റ്റ് ചെയ്യുന്നു, ഓരോ സ്ഥാപനത്തിനും ഒരു വരി, അതിന്റെ തുറന്ന ടാസ്കുകൾ, ബാക്കിയുള്ള മണിക്കൂറുകൾ, എത്രയെണ്ണം വൈകി എന്നിവയോടെ. കാലാവധി കഴിഞ്ഞ ടാസ്ക് ഡൈജസ്റ്റ്, AI ബ്രീഫിംഗുകൾ, **AI യോട് ചോദിക്കുക** എന്നിവയെല്ലാം വൈകിയ ഏത് ജോലിയാണ് ഒരു കോൺട്രാക്ടറുടെ പക്കലുള്ളതെന്ന് പറയുന്നു, ഒരു ടാസ്ക് ഒരാൾക്ക് നൽകാൻ AI യോട് ചോദിക്കുക നിർദ്ദേശിക്കുകയും ചെയ്യാം.',
            'p4' => '**കോൺട്രാക്ടർമാർക്ക് ഇമെയിൽ അയയ്ക്കുക** (Projects - Settings - General) തുടക്കത്തിൽ ഓഫ് ആണ്: കോൺട്രാക്ടർ ജോലി ഇവിടെ ട്രാക്ക് ചെയ്യപ്പെടുന്നു, നിങ്ങൾ തന്നെ അത് പിന്തുടരുന്നു. ഇത് ഓൺ ആക്കിയാൽ, ഒരു ടാസ്ക് അവർക്ക് നൽകുമ്പോൾ, അത് കാലാവധിക്ക് രണ്ട് ദിവസം മുമ്പ്, അത് നഷ്ടമായാൽ ഒരിക്കൽ, സ്ഥാപനത്തിലെ വ്യക്തിക്ക് ഇമെയിൽ അയയ്ക്കും - നിങ്ങളുടെ ഔട്ട്ഗോയിംഗ് മെയിൽബോക്സിൽ നിന്ന്, ടാസ്ക്, തീയതികൾ, ഇവിടെ ആർക്ക് മറുപടി നൽകണം എന്നിവയോടെ. ഇമെയിൽ വിലാസമുള്ള ഒരാൾ ഉള്ള ടാസ്കുകൾ മാത്രമേ അയയ്ക്കൂ; ഓരോ ഇമെയിലും അയയ്ക്കൽ ലോഗിൽ **കോൺട്രാക്ടർക്കുള്ള ടാസ്ക്** ആയി ഉണ്ടാകും.',
        ],
        'connections' => [
            'nav' => 'കണക്ഷനുകൾ',
            'title' => 'ഒരു പ്രോജക്റ്റിനെ മറ്റെല്ലാറ്റുമായി ബന്ധിപ്പിക്കുക',
            'intro' => 'ഉപകരണങ്ങൾ, മാറ്റങ്ങൾ, ടിക്കറ്റുകൾ, കരാറുകൾ, കോൺഫിഗറേഷൻ ഐറ്റങ്ങൾ, അറിവ്, പ്രശ്നങ്ങൾ.',
            'p1' => 'Connections ടാബ് ഒരു പ്രോജക്റ്റിനെ അത് സ്പർശിക്കുന്ന റെക്കോർഡുകളുമായി ലിങ്ക് ചെയ്യുന്നു: മാറ്റിസ്ഥാപിക്കുന്ന ലാപ്ടോപ്പുകൾ, അത് ഉയർത്തുന്ന മാറ്റങ്ങൾ (അവയ്ക്ക് അനുമതി ലഭിച്ചോ എന്നതോടെ), അത് ഉണ്ടാക്കിയ ടിക്കറ്റുകൾ, അത് ആശ്രയിക്കുന്ന വിതരണക്കാരുടെ കരാറുകൾ, CMDB-യിലെ സിസ്റ്റങ്ങൾ, Knowledge-ലെ റൺബുക്കുകൾ, പരിഹരിക്കാനായി നിലനിൽക്കുന്ന പ്രശ്നങ്ങൾ. തിരയാൻ ഒരു തരത്തിന് താഴെയുള്ള ബോക്സിൽ ടൈപ്പ് ചെയ്യുക, ലിങ്ക് ചെയ്യാൻ ഒരു ഫലം തിരഞ്ഞെടുക്കുക. ഓരോന്നിലും എത്രയെണ്ണം ബന്ധിപ്പിച്ചിട്ടുണ്ടെന്ന് ഓവർവ്യൂ കാണിക്കുന്നു.',
            'p2' => 'ഒരു തരത്തിന്റെ മൊഡ്യൂൾ തുറക്കാൻ കഴിയുമെങ്കിൽ മാത്രമേ നിങ്ങൾ അത് കാണൂ, മറുവശത്തെ റെക്കോർഡ് തുറക്കാൻ കഴിയുമെങ്കിൽ മാത്രമേ ലിങ്ക് കാണൂ. ഒന്നിലധികം കമ്പനികളുള്ള ഇൻസ്റ്റലേഷനിൽ, ഉപകരണങ്ങൾ, മാറ്റങ്ങൾ, ടിക്കറ്റുകൾ, പ്രശ്നങ്ങൾ, കോൺഫിഗറേഷൻ ഐറ്റങ്ങൾ എന്നിവ പ്രോജക്റ്റിന്റെ സ്വന്തം കമ്പനിയുടേതായിരിക്കണം. ലിങ്ക് നീക്കുന്നത് റെക്കോർഡിനെ ഒരിക്കലും മാറ്റില്ല, രണ്ടും പ്രോജക്റ്റിന്റെ ചരിത്രത്തിൽ രേഖപ്പെടുത്തും.',
            'p3' => 'ഓരോ റെക്കോർഡും അതിന്റെ പ്രോജക്റ്റുകൾ സ്വന്തം വശത്തുനിന്നും കാണിക്കുന്നു. ഒരു **പ്രശ്നത്തിന്** അത് ഉൾപ്പെടുന്ന പ്രോജക്റ്റുകളെ അവയുടെ ഹെൽത്തും പുരോഗതിയും സഹിതം ലിസ്റ്റ് ചെയ്യുന്ന ഒരു **Projects** പാനൽ ഉണ്ട്, അവിടെ നിന്ന് ഒരു ലൈവ് പ്രോജക്റ്റിലേക്ക് ലിങ്ക് ചെയ്യാൻ **പ്രോജക്റ്റിലേക്ക് ചേർക്കുക** - പ്രോജക്റ്റിന്റെ Connections ടാബിലെ അതേ ലിങ്ക് തന്നെ.',
        ],
        'calendar' => [
            'nav' => 'കലണ്ടറിൽ',
            'title' => 'കലണ്ടറിൽ പ്രോജക്റ്റ് തീയതികൾ',
            'intro' => 'ലക്ഷ്യ അവസാന തീയതികൾ, ഘട്ട അവസാനങ്ങൾ, മൈൽസ്റ്റോണുകൾ - ടീം ഇതിനകം നോക്കുന്നിടത്ത്.',
            'p1' => 'നിർദ്ദേശിച്ചതോ സജീവമായതോ ആയ ഓരോ പ്രോജക്റ്റും അതിന്റെ ലക്ഷ്യ അവസാന തീയതി പങ്കിട്ട കലണ്ടറിൽ "Project due" ആയി ഇടുന്നു, അടച്ചിട്ടില്ലാത്ത ഓരോ ഘട്ടവും, ഫേസും, സ്പ്രിന്റും അതിന്റെ അവസാന തീയതിയും അവിടെ ഇടുന്നു, ഓരോ മൈൽസ്റ്റോണും എത്തുന്നതുവരെ അതുപോലെ തന്നെ. അവ Projects എന്ന വിഭാഗത്തിലെ ദിവസം മുഴുവൻ എൻട്രികളാണ്, കലണ്ടറിൽ നിങ്ങൾക്ക് അതിന്റെ പേരോ നിറമോ മാറ്റാം. പ്രോജക്റ്റിൽ ഒരു തീയതി മാറ്റിയാൽ കലണ്ടർ അത് പിന്തുടരും; ഒരു ഘട്ടം അടയ്ക്കുകയോ പ്രോജക്റ്റ് ഹോൾഡിൽ വയ്ക്കുകയോ അടയ്ക്കുകയോ റദ്ദാക്കുകയോ ചെയ്താൽ അതിന്റെ എൻട്രികൾ പോകും. കലണ്ടർ അവയെല്ലാം കാണിക്കണോ, ലക്ഷ്യ അവസാന തീയതികൾ മാത്രമോ, ഒന്നുമില്ലയോ എന്ന് **Projects - Settings - General** തിരഞ്ഞെടുക്കുന്നു.',
            'p2' => 'എൻട്രികൾ എഴുതുന്നത് Projects ആണ്, അതിനാൽ കലണ്ടറിൽ അവയിലൊന്നിൽ വരുത്തുന്ന മാറ്റം ഏതെങ്കിലും പ്രോജക്റ്റ് അടുത്ത തവണ മാറുമ്പോൾ മാറ്റിസ്ഥാപിക്കപ്പെടും. മറ്റ് ഓട്ടോമാറ്റിക് എൻട്രികളെപ്പോലെ അവയുടെ വാചകം ഇംഗ്ലീഷിലാണ്. കലണ്ടർ എൻട്രികൾക്ക് കമ്പനി ഇല്ല, അതിനാൽ ഒന്നിലധികം കമ്പനികളുള്ള ഇൻസ്റ്റലേഷനിൽ കലണ്ടർ തുറക്കാൻ കഴിയുന്ന എല്ലാവരും എല്ലാ പ്രോജക്റ്റിന്റെയും തീയതികൾ കാണും.',
        ],
        'alerts' => [
            'nav' => 'അലേർട്ടുകളും വർക്ക്ഫ്ലോകളും',
            'title' => 'അലേർട്ടുകൾ, Workflows-ലെ പ്രോജക്റ്റുകൾ',
            'intro' => 'എന്തെങ്കിലും ശ്രദ്ധിക്കേണ്ടി വരുമ്പോൾ പ്രോജക്റ്റ് മാനേജർ അറിയുന്നു, Workflows-ന് അതിൽ പ്രവർത്തിക്കാനും കഴിയും.',
            'p1' => 'ഒരു പ്രോജക്റ്റിന്റെ ഹെൽത്ത് മാറുമ്പോൾ (പച്ച, ആംബർ അല്ലെങ്കിൽ ചുവപ്പ്, കണക്കാക്കിയതോ കൈകൊണ്ട് സജ്ജമാക്കിയതോ), അത് സമയ ടോളറൻസോ റിസ്ക് ടോളറൻസോ കടക്കുമ്പോൾ, ഒരു ഘട്ടം, ഫേസ് അല്ലെങ്കിൽ സ്പ്രിന്റ് 7 ദിവസത്തിനുള്ളിൽ അവസാനിക്കുമ്പോഴും തലേദിവസം വീണ്ടും, ഒരു മൈൽസ്റ്റോൺ 7 ദിവസം അകലെയായിരിക്കുമ്പോഴും തലേദിവസവും അത് നഷ്ടമായാലും, ആരെങ്കിലും ഒരു മാറ്റ അഭ്യർത്ഥന ഉയർത്തുകയോ അംഗീകരിക്കുകയോ നിരസിക്കുകയോ ചെയ്യുമ്പോഴും നോട്ടിഫിക്കേഷൻ ബെൽ പ്രോജക്റ്റിന്റെ മാനേജരെ അറിയിക്കുന്നു. ഓരോന്നും സംഭവിക്കുമ്പോൾ ഒരിക്കൽ മാത്രം പറയും: ചുവപ്പായി തുടരുന്ന പ്രോജക്റ്റ് ഓരോ മണിക്കൂറിലും മുഴങ്ങില്ല, മാറിയിട്ട് തിരിച്ചുവരുന്ന ലംഘനം പുതിയ വാർത്തയാണ്. സ്വയം വരുത്തിയ മാറ്റത്തെക്കുറിച്ച് ആരെയും അറിയിക്കില്ല. ഓരോ വ്യക്തിക്കും ഇവ ഓഫ് ആക്കാം, അല്ലെങ്കിൽ ഒരു ഘട്ടം അടയ്ക്കുമ്പോഴോ മൈൽസ്റ്റോൺ എത്തുമ്പോഴോ ഒരു ബെൽ ഓൺ ആക്കാം, **Preferences - Notifications** എന്നതിൽ.',
            'p2' => 'ഇതേ നിമിഷങ്ങൾ **Workflows**-ൽ ട്രിഗ്ഗറുകളാണ്: ഒരു പ്രോജക്റ്റിന്റെ ഹെൽത്ത് മാറുന്നു, ഒരു ടോളറൻസ് ലംഘിക്കപ്പെടുന്നു, ഒരു ഘട്ടം അടയ്ക്കുന്നു, ഒരു ഘട്ടം ഉടൻ അവസാനിക്കുന്നു, ഒരു മൈൽസ്റ്റോൺ അടുത്തുവരുന്നു, നഷ്ടമാകുന്നു അല്ലെങ്കിൽ എത്തുന്നു, ഒരു മാറ്റ അഭ്യർത്ഥന ഉയർത്തുകയോ തീരുമാനിക്കുകയോ ചെയ്യുന്നു, ഒരു പ്രോജക്റ്റ് സൃഷ്ടിക്കുകയോ അപ്ഡേറ്റ് ചെയ്യുകയോ ഇല്ലാതാക്കുകയോ ചെയ്യുന്നു. പ്രോജക്റ്റിന്റെ പേര്, കോഡ്, ഹെൽത്ത്, മാനേജർ, തീയതികൾ എന്നിവ ഉപയോഗിച്ച്, ഒരു പ്രോജക്റ്റ് ചുവപ്പാകുമ്പോൾ Teams-ലോ Slack-ലോ പോസ്റ്റ് ചെയ്യാനും, ഒരു ടോളറൻസ് ലംഘിക്കപ്പെടുമ്പോൾ ടിക്കറ്റ് ഉണ്ടാക്കാനും, ഒരു ഘട്ടം അടയ്ക്കുമ്പോൾ ബോർഡിന് ഇമെയിൽ അയയ്ക്കാനും ഒരു വർക്ക്ഫ്ലോയ്ക്ക് കഴിയും.',
            'p3' => 'ഹെൽത്തും ടോളറൻസുകളും പ്ലാനിൽ നിന്നാണ് കണക്കാക്കുന്നത്, അതിനാൽ ആരെങ്കിലും നോക്കണം. ഒരു പ്രോജക്റ്റിൽ എന്തെങ്കിലും സേവ് ചെയ്യുന്നത് ഉടൻ നോക്കും; അല്ലെങ്കിൽ ഷെഡ്യൂൾ ചെയ്ത വർക്ക്ഫ്ലോ ജോബ് അത് ചെയ്യും (cron/workflow_scheduled.php, മണിക്കൂറിൽ ഒരിക്കൽ ധാരാളം), ഷെഡ്യൂൾ ചെയ്ത ജോബുകൾ ഇല്ലാത്ത ഇൻസ്റ്റലേഷനിൽ, പോർട്ട്ഫോളിയോ തുറക്കുന്നത് 15 മിനിറ്റിൽ ഒരിക്കലിൽ കൂടുതൽ നോക്കില്ല. രാത്രിയിൽ ഒരു ടാസ്കിന്റെ കാലാവധി കഴിയുന്നത് ഇവയിൽ ആദ്യം വരുന്നത് ശ്രദ്ധിക്കും.',
            'p4' => '**ഓർമ്മപ്പെടുത്തലുകൾ.** ഓരോ പ്രോജക്റ്റ് മാനേജർക്കും അവരുടെ സജീവ പ്രോജക്റ്റിന്റെ **കാലാവധി കഴിഞ്ഞ ടാസ്കുകൾ** ലിസ്റ്റ് ചെയ്യുന്ന ഒരു ബെൽ ലഭിക്കും - ആഴ്ചതോറും തിങ്കളാഴ്ച, ദിവസവും, അല്ലെങ്കിൽ ഒരിക്കലുമില്ല (Projects -> Settings -> General, *Overdue task digest*). ഒരു നിർദ്ദേശം, മാറ്റ അഭ്യർത്ഥന, ഗേറ്റ് സൈൻ-ഓഫ് അല്ലെങ്കിൽ റിപ്പോർട്ട് ഡ്രാഫ്റ്റ് ഒരു തീരുമാനത്തിനായി **3 ദിവസം** കാത്തിരുന്നാൽ, അത് തീരുമാനിക്കുന്നവരെ ഓർമ്മിപ്പിക്കും - *ഇപ്പോഴും നിങ്ങളുടെ സൈൻ-ഓഫിനായി കാത്തിരിക്കുന്നു* - ഓരോ 3 ദിവസത്തിലും വീണ്ടും (*Nudge after*; 0 = ഓർമ്മപ്പെടുത്തലുകളില്ല). 45 ദിവസത്തിൽ കൂടുതൽ പഴക്കമുള്ളതൊന്നും ഓർമ്മപ്പെടുത്തില്ല.',
            'p5' => 'ബെൽ ഇവയും അറിയിക്കുന്നു: ആരെങ്കിലും ഒരു RAID എൻട്രി എസ്കലേറ്റ് ചെയ്യുമ്പോൾ പ്രോജക്റ്റ് മാനേജരെ; ഒരു പുതിയ നിർദ്ദേശത്തെക്കുറിച്ച് അംഗീകരിക്കുന്നവരെയും, തീരുമാനത്തെക്കുറിച്ച് അത് നിർദ്ദേശിച്ചയാളെയും; ഒരു ഗേറ്റിൽ സൈൻ-ഓഫ് ആവശ്യമുള്ളപ്പോൾ പേര് നൽകിയ വ്യക്തിയെ; ഒരു അവലോകനം വരാനുള്ളപ്പോൾ, അടച്ചതിന് ശേഷവും, ഒരു ആനുകൂല്യത്തിന്റെ ഉടമയെയും പ്രോജക്റ്റ് മാനേജരെയും; ഷെഡ്യൂൾ ചെയ്ത റിപ്പോർട്ട് ഡ്രാഫ്റ്റ് ചെയ്യുമ്പോൾ പ്രോജക്റ്റ് മാനേജരെ. ഇവയോരോന്നും, കാലാവധി കഴിഞ്ഞ ഡൈജസ്റ്റും, ഓർമ്മപ്പെടുത്തലുകളും **Workflows**-ലും ട്രിഗ്ഗറുകളാണ്.',
        ],
        'budget' => [
            'nav' => 'ബജറ്റ്',
            'title' => 'ബജറ്റ്: ആസൂത്രണം ചെയ്തതും യഥാർത്ഥവും',
            'intro' => 'പ്രോജക്റ്റിന് എത്ര ചെലവാകുമെന്ന് കരുതിയിരുന്നു, എത്ര ചെലവായി, ഇവ തമ്മിൽ എത്ര വ്യത്യാസമുണ്ട്.',
            'p1' => 'ബജറ്റ് ടാബ് (ഘട്ടങ്ങളുള്ള പ്രോജക്റ്റുകൾക്ക് ഓണാണ്; മറ്റുള്ളവയ്ക്ക് Tools-ന് കീഴിൽ ഓണാക്കുക) ആസൂത്രണം ചെയ്ത ബജറ്റ്, യഥാർത്ഥ ചെലവ്, ബാക്കിയുള്ളത്, എത്ര ഉപയോഗിച്ചു എന്നിവ കാണിക്കുന്നു. ചെലവാകുമെന്ന് പ്രതീക്ഷിക്കുന്ന ഓരോ കാര്യത്തിനും - ഹാർഡ്‌വെയർ, ലൈസൻസുകൾ, വിതരണക്കാർ - ഒരു **ബജറ്റ് ലൈൻ** ചേർക്കുക, ആസൂത്രണം ചെയ്തതും ചെലവായതും സഹിതം. ഒരു ലൈനിന് Connections ടാബിൽ ലിങ്ക് ചെയ്ത ഒരു കരാറിന്റെ പേര് നൽകാം: അതിന്റെ യഥാർത്ഥ തുക ഒഴിച്ചിട്ടാൽ കരാറിന്റെ മൂല്യം ഉപയോഗിക്കും. പ്രോജക്റ്റിന്റെ കമ്പനിയിലെ ഒരു കോസ്റ്റ് സെന്ററും അതിൽ ഉൾപ്പെടുത്താം.',
            'p2' => '**ലേബർ** എന്നത് പ്രോജക്റ്റിന്റെ ടാസ്കുകളിൽ രേഖപ്പെടുത്തിയ സമയമാണ്. Projects - Settings - Budget ആണ് അത് മണിക്കൂറുകളായി കാണിക്കണോ, ഒരു മണിക്കൂർ നിരക്കിൽ (പ്രോജക്റ്റിന് അത് മാറ്റാം) വില നിശ്ചയിക്കണോ, അതോ ഓരോ അനലിസ്റ്റിന്റെയും നിരക്കിൽ വില നിശ്ചയിക്കണോ എന്ന് തീരുമാനിക്കുന്നത്. ഓരോ നിരക്കും ഒരു തീയതി മുതൽ ബാധകമാകുന്നു, അതിനാൽ പുതിയ നിരക്ക് ഇതിനകം രേഖപ്പെടുത്തിയ സമയത്തിന്റെ വില മാറ്റില്ല, ക്രമീകരണം മാറ്റുന്നത് ഒന്നും തിരുത്തിയെഴുതുന്നില്ല - സമയം സമയമായിത്തന്നെ സൂക്ഷിക്കുന്നു.',
            'p4' => '**പണം എവിടേക്ക് പോകുന്നു** ഓരോ വിഭാഗത്തിനും ആസൂത്രണം ചെയ്തതും യഥാർത്ഥവും ചാർട്ടിൽ കാണിക്കുന്നു, വില നിശ്ചയിച്ച ശേഷം ലേബറും ഉൾപ്പെടെ. **പട്ടിക** അതേ കണക്കുകൾ പട്ടികയായി കാണിക്കുന്നു.',
            'p5' => 'ഒരു ലൈനിന് **എപ്പോൾ** എന്നും പറയാം: പണം ചെലവാകുമെന്ന് ആസൂത്രണം ചെയ്ത തീയതിയും ചെലവായ തീയതിയും. **കാലക്രമേണയുള്ള ചെലവ്** അവയെ ദിവസം തോറും കൂട്ടുന്നു - ആസൂത്രണം ചെയ്തതും ഇതുവരെ ചെലവായതും - ഇന്ന് മുതൽ ലക്ഷ്യ പൂർത്തീകരണം വരെ ഡാഷ് ചെയ്ത **ഫോർകാസ്റ്റ്** സഹിതം, കൂടാതെ ബജറ്റ്, ഏറ്റവും പുതിയ ബേസ്‌ലൈനിന്റെ ബജറ്റ്, അധികച്ചെലവ് സഹിഷ്ണുത എന്നിവ താരതമ്യം ചെയ്യാനുള്ള ലൈനുകളായും. **ഫോർകാസ്റ്റ്** എന്നത് പ്രോജക്റ്റിന് ഇപ്പോൾ എത്ര ചെലവാകുമെന്ന് പ്രതീക്ഷിക്കുന്നതാണ്: ഓരോ ലൈനിന്റെയും സ്വന്തം ഫോർകാസ്റ്റ് (ഒന്ന് ടൈപ്പ് ചെയ്യുക, ഇല്ലെങ്കിൽ ആസൂത്രണം ചെയ്തതിലും ചെലവായതിലും വലുത്), കൂടാതെ ലേബർ - രേഖപ്പെടുത്തിയതും, തുറന്ന ടാസ്കുകളുടെ എസ്റ്റിമേറ്റുകളിൽ ഇനിയും വരാനുള്ളതും, ഇന്നത്തെ നിരക്കിൽ വില നിശ്ചയിച്ചത്. യഥാർത്ഥ തുകയില്ലാത്ത ഒരു ലേബർ ലൈൻ ലേബറിനുള്ള പദ്ധതിയാണ്, അതിനാൽ ലേബർ ഒരിക്കലും രണ്ടുതവണ കണക്കാക്കില്ല. എസ്റ്റിമേറ്റുകൾ കണക്കാക്കണോ, **അധികച്ചെലവ് അനുവദനീയം** ചെലവായതിനെയാണോ അതോ (നേരത്തെ മുന്നറിയിപ്പ് നൽകുന്ന) ഫോർകാസ്റ്റിനെയാണോ അളക്കേണ്ടത് എന്നിവ Projects - Settings - Budget തീരുമാനിക്കുന്നു.',
            'p3' => 'ഓരോ പ്രോജക്റ്റും ഉണ്ടാക്കിയ **കറൻസി** തന്നെ നിലനിർത്തുന്നു, വ്യത്യസ്ത കറൻസികളിലെ തുകകൾ ഒരിക്കലും കൂട്ടിച്ചേർക്കില്ല: മറ്റൊരു കറൻസിയിലുള്ള കരാർ അതിന്റെ ലൈനിൽ കാണിക്കും, പക്ഷേ കണക്കാക്കില്ല. പ്രോജക്റ്റുകൾക്ക് തിരഞ്ഞെടുക്കാൻ Projects - Settings അനുവദിക്കുന്നുണ്ടെങ്കിൽ, Currency ബട്ടൺ പ്രോജക്റ്റിന്റെ ലേബൽ മാറ്റുന്നു - പരിവർത്തനം ചെയ്യുന്നില്ല. Gates ടാബിൽ, **അധികച്ചെലവ് അനുവദനീയം** ഒരു ചെലവ് സഹിഷ്ണുത നിശ്ചയിക്കുന്നു: ബജറ്റിനേക്കാൾ അതിലധികം കൂടിയാൽ പ്രോജക്റ്റ് ഒരു അപവാദമാകുകയും Off track ആകുകയും ചെയ്യും.',
            'p6' => '**എർണ്ഡ് വാല്യു** മൂന്ന് ലൈനുകൾ താരതമ്യം ചെയ്യുന്നു: പ്ലാൻഡ് വാല്യു (ലൈനുകളുടെ ആസൂത്രിത തീയതികൾ പ്രകാരം ചെലവാകുമെന്ന് കരുതിയ ബജറ്റ്), എർണ്ഡ് വാല്യു (ബജറ്റ് ഗുണം ചെയ്ത ജോലിയുടെ അനുപാതം - എസ്റ്റിമേറ്റ് ചെയ്ത മണിക്കൂറുകൾ പ്രകാരം, എസ്റ്റിമേറ്റുകൾ ഇല്ലെങ്കിൽ ടാസ്കുകൾ പ്രകാരം), യഥാർത്ഥ ചെലവ്. **CPI** എന്നത് എർണ്ഡ് വാല്യുവിനെ യഥാർത്ഥ ചെലവ് കൊണ്ട് ഹരിച്ചത് - 1-ന് താഴെയാണെങ്കിൽ, ചെയ്ത ജോലിക്ക് ഉദ്ദേശിച്ചതിലും കൂടുതൽ ചെലവായി; **SPI** എന്നത് എർണ്ഡ് വാല്യുവിനെ പ്ലാൻഡ് വാല്യു കൊണ്ട് ഹരിച്ചത് - 1-ന് താഴെയാണെങ്കിൽ, പദ്ധതിയേക്കാൾ പിന്നിൽ; **എസ്റ്റിമേറ്റ് അറ്റ് കംപ്ലീഷൻ** എന്നത് ബജറ്റിനെ CPI കൊണ്ട് ഹരിച്ചതാണ്.',
        ],
        'benefits' => [
            'nav' => 'ബെനിഫിറ്റുകൾ',
            'title' => 'ബെനിഫിറ്റുകൾ: പ്രോജക്റ്റ് ഫലം കണ്ടോ?',
            'intro' => 'പ്രോജക്റ്റ് എന്താണ് മെച്ചപ്പെടുത്തേണ്ടത്, തുടങ്ങിയ നിലയിൽ നിന്ന് അളക്കുന്നത് - ഭൂരിഭാഗം ബെനിഫിറ്റുകളും ലഭിക്കുന്ന പ്രോജക്റ്റ് അടച്ച ശേഷം അവലോകനം ചെയ്യുന്നതും.',
            'p1' => '**ബെനിഫിറ്റുകൾ** ടാബ് (ഘട്ടങ്ങളുള്ള പ്രോജക്റ്റുകൾക്ക് ഓണാണ്; മറ്റുള്ളവയ്ക്ക് Tools-ന് കീഴിൽ ഓണാക്കുക) പ്രോജക്റ്റ് മെച്ചപ്പെടുത്തേണ്ടവ പട്ടികപ്പെടുത്തുന്നു. ഒന്ന് **ചേർക്കുക**: എന്ത് മെച്ചപ്പെടുന്നു, എങ്ങനെ അളക്കുന്നു, ഏത് യൂണിറ്റിൽ, ഏത് ദിശയാണ് മെച്ചം (ഉയർന്നത് അല്ലെങ്കിൽ താഴ്ന്നത്), **ബേസ്‌ലൈൻ** (ഇന്നത്തെ നില), **ടാർഗെറ്റ്**, അത് കൈവരിക്കേണ്ട തീയതി, ഒരു ഉടമ, എപ്പോൾ അവലോകനം ചെയ്യുന്നു. ഓരോ ബെനിഫിറ്റും ബേസ്‌ലൈൻ, ഇപ്പോഴത്തെ നില, ടാർഗെറ്റ് എന്നിവ എത്ര ദൂരം എത്തി എന്നതിനൊപ്പം അടുത്തടുത്ത് കാണിക്കുന്നു, കൂടാതെ ഇവയിലൊന്നും: ഇതുവരെ അളന്നിട്ടില്ല, പുരോഗതിയിൽ, കൈവരിച്ചു, അല്ലെങ്കിൽ ടാർഗെറ്റ് തീയതി നഷ്ടപ്പെട്ടു.',
            'p2' => '**രേഖപ്പെടുത്തുക** ഒരു അളവ് ചേർക്കുന്നു - ഒരു മൂല്യവും അളന്ന തീയതിയും. ഏറ്റവും പുതിയത് "ഇപ്പോഴത്തെ നില" ആണ്. അവലോകന തീയതിയിലോ അതിനടുത്തോ (14 ദിവസം വരെ നേരത്തെ) രേഖപ്പെടുത്തിയാൽ അത് അവലോകനമായി കണക്കാക്കും, അടുത്ത അവലോകനം ബെനിഫിറ്റിന്റെ ഇടവേള അനുസരിച്ച് നീങ്ങും; ഇടവേള 0 ആണെങ്കിൽ ഒരിക്കൽ മാത്രം അവലോകനം ചെയ്യും. **ചരിത്രം** എല്ലാ അളവുകളും പട്ടികപ്പെടുത്തുന്നു. ഒരു ബെനിഫിറ്റ് ഇനി നിരീക്ഷിക്കേണ്ടതില്ലെങ്കിൽ, അത് എഡിറ്റ് ചെയ്ത് **ഈ ബെനിഫിറ്റ് അവലോകനം ചെയ്യുന്നത് നിർത്തുക** ടിക്ക് ചെയ്യുക.',
            'p3' => 'ഒരു അവലോകന തീയതി എത്തുമ്പോൾ ബെൽ ബെനിഫിറ്റിന്റെ ഉടമയെയും പ്രോജക്റ്റ് മാനേജരെയും അറിയിക്കുന്നു (Projects - Settings - General-ൽ ഇത് ഉടമയ്ക്ക് മാത്രമാക്കാം) - **പ്രോജക്റ്റ് അടച്ച ശേഷവും**; റദ്ദാക്കിയ പ്രോജക്റ്റ് അവലോകനം ചെയ്യില്ല. Overview-യും പോർട്ട്ഫോളിയോ കാർഡും കാലാവധിയായ അവലോകനങ്ങൾ കാണിക്കുന്നു, Reports ടാബിലെ **Closure** റിപ്പോർട്ടിൽ എല്ലാ ബെനിഫിറ്റുകളും ഉൾപ്പെടുന്നു: എന്ത് കൈവരിച്ചു, ഇനി എന്ത് വരാനുണ്ട്.',
        ],
        'intake' => [
            'nav' => 'നിർദ്ദേശങ്ങളും അനുമതിയും',
            'title' => 'ഒരു പ്രോജക്റ്റ് നിർദ്ദേശിക്കുന്നതും അനുമതി നൽകുന്നതും',
            'intro' => 'ഒരു ഫോമിലെ "നമുക്ക് ഇത് കിട്ടുമോ..." എന്നതിൽ നിന്ന് അനുമതി ലഭിച്ച പ്രോജക്റ്റിലേക്ക്, അതിനുള്ള ന്യായം എഴുതിവച്ചുകൊണ്ട്.',
            'p1' => 'ഏത് ഫോമിനും ഒരു പ്രോജക്റ്റ് നിർദ്ദേശിക്കാം. **Forms**-ൽ ഫോം തുറന്ന്, **What happens next**-ലേക്ക് പോയി "When submitted" എന്നതിന് കീഴിൽ (അല്ലെങ്കിൽ ആദ്യം അനുമതി ലഭിക്കുന്ന ഫോമിന് "When approved" എന്നതിന് കീഴിൽ) **Create a project proposal** ചേർക്കുക. അതിന്റെ ബോക്സുകൾ ഒഴിച്ചിട്ടാൽ പ്രോജക്റ്റിന് ഫോമിന്റെയും അയച്ചയാളുടെയും പേര് ലഭിക്കും, സംഗ്രഹം അവരുടെ ഉത്തരങ്ങളായിരിക്കും, അത് അവരുടെ കമ്പനിയുടേതായിരിക്കും; അല്ലെങ്കിൽ അവ പൂരിപ്പിക്കുക - പേര്, എന്തുകൊണ്ട് ആവശ്യമാണ്, കണക്കാക്കിയ ചെലവ്, പ്രതീക്ഷിക്കുന്ന ബെനിഫിറ്റ്, ആവശ്യമുള്ള തീയതി, എങ്ങനെ നടത്തുന്നു, മുൻഗണന, പ്രോജക്റ്റ് മാനേജർ - ഉത്തരങ്ങൾ ഉപയോഗിച്ച്, {{submission.fields.Budget}} പോലെ. **Workflows**-ലെ ഏത് റൂളിലും ഇതേ പ്രവർത്തനം ഉപയോഗിക്കാം.',
            'p2' => 'ഒരു നിർദ്ദേശം അതിന്റെ Overview-ൽ ഒരു **Proposal** പാനൽ കാണിക്കുന്നു - ആര് നിർദ്ദേശിച്ചു, ഏത് ഫോമിൽ, കണക്കാക്കിയ ചെലവ്, പ്രതീക്ഷിക്കുന്ന ബെനിഫിറ്റ്, എന്തുകൊണ്ട് ആവശ്യമാണ് - കൂടാതെ പോർട്ട്ഫോളിയോയിൽ ഒരു **അനുമതിക്കായി കാത്തിരിക്കുന്നു** ചിപ്പും വ്യൂവും. അനുമതി ലഭിക്കുന്നതുവരെ അത് Proposed ആയി തുടരുകയോ റദ്ദാക്കുകയോ ചെയ്യാം, മറ്റൊന്നും പറ്റില്ല. അനുമതി നൽകുന്നയാൾ **Approve** അമർത്തുന്നു (അത് Proposed ആയി തുടരുകയും പ്രോജക്റ്റ് മാനേജർക്ക് തുടങ്ങാൻ വിടുകയും ചെയ്യും, അല്ലെങ്കിൽ ഉടൻ തുടങ്ങും - ഒരു ക്രമീകരണം) അല്ലെങ്കിൽ ഒരു കാരണത്തോടെ **Reject** ചെയ്യുന്നു (അത് റദ്ദാക്കപ്പെടും; ഒന്നും ഇല്ലാതാക്കില്ല). പുതിയ നിർദ്ദേശത്തെക്കുറിച്ച് അനുമതി നൽകുന്നവരെ ബെല്ലിൽ അറിയിക്കുന്നു; നിർദ്ദേശിച്ചയാളെ തീരുമാനം അറിയിക്കുന്നു, "ഒരു പ്രോജക്റ്റ് നിർദ്ദേശം അംഗീകരിക്കുകയോ നിരസിക്കുകയോ ചെയ്യുമ്പോൾ" എന്നതിലുള്ള ഒരു വർക്ക്ഫ്ലോയ്ക്ക് ഫോമിൽ ചോദിച്ച ഒരാൾക്ക് ഇമെയിൽ അയയ്ക്കാം.',
            'p3' => 'ഏത് പുതിയ പ്രോജക്റ്റുകൾക്ക് അനുമതി വേണം (ഫോമിൽ നിർദ്ദേശിച്ചവ - സ്ഥിരസ്ഥിതി -, ഓരോ പുതിയ പ്രോജക്റ്റും, അല്ലെങ്കിൽ ഒന്നും വേണ്ട), ആര് അനുമതി നൽകുന്നു (Projects മാനേജ് ചെയ്യുന്നവർ, അല്ലെങ്കിൽ പേരുള്ള ഒരാൾ - Manage Projects ഉള്ളവർക്കും എപ്പോഴും തീരുമാനിക്കാം), അനുമതി നൽകുന്നത് എന്ത് ചെയ്യുന്നു എന്നിവ Projects - Settings - General തീരുമാനിക്കുന്നു. ക്രമീകരണം ഓണാക്കുന്നതിന് മുമ്പ് ഉണ്ടാക്കിയ പ്രോജക്റ്റുകളെ ഇത് ഒരിക്കലും ബാധിക്കില്ല.',
        ],
        'control' => [
            'nav' => 'മാറ്റ നിയന്ത്രണം',
            'title' => 'മാറ്റ നിയന്ത്രണം: ബേസ്‌ലൈനുകളും മാറ്റ അഭ്യർത്ഥനകളും',
            'intro' => 'എന്താണ് സമ്മതിച്ചത്, അതിനുശേഷം പദ്ധതി എത്ര വ്യതിചലിച്ചു, അത് മാറ്റാൻ ആരാണ് സമ്മതിച്ചത്.',
            'p1' => 'ഒരു **ബേസ്‌ലൈൻ** സമ്മതിച്ച രൂപത്തിൽ പദ്ധതിയെ രേഖപ്പെടുത്തുന്നു: ആരംഭവും ലക്ഷ്യ പൂർത്തീകരണവും, ആസൂത്രണം ചെയ്ത ബജറ്റ്, ടാസ്കുകളും എസ്റ്റിമേറ്റ് ചെയ്ത മണിക്കൂറുകളും, Must ഇനങ്ങൾ, ഓരോ ഘട്ടവും, മൈൽസ്റ്റോണും, ബജറ്റ് ലൈനും. Change control ടാബ് (ഘട്ടങ്ങളുള്ള പ്രോജക്റ്റുകൾക്ക് ഓണാണ്; മറ്റുള്ളവയ്ക്ക് Tools-ന് കീഴിൽ ഓണാക്കുക) അതിനെ ഇപ്പോഴത്തെ പദ്ധതിയുമായി താരതമ്യം ചെയ്യുന്നു - പൂർത്തീകരണത്തിൽ **+17 ദിവസം**, ബജറ്റിൽ **+£4,950 (+20%)** - എന്നിട്ട് എന്തെല്ലാം നീങ്ങി എന്ന് ഇനം ഇനമായി പട്ടികപ്പെടുത്തുന്നു: രണ്ടാഴ്ച വൈകിയ ഒരു മൈൽസ്റ്റോൺ, വലുതായ ഒരു ബജറ്റ് ലൈൻ, ചേർത്ത ഒരു Must ഇനം. അതുമായി അളക്കാൻ **Compare with** എന്നതിന് കീഴിൽ പഴയ ഒരു ബേസ്‌ലൈൻ തിരഞ്ഞെടുക്കുക. കൈകൊണ്ട് ഒന്ന് എടുക്കാൻ **Baseline** അമർത്തുക, വേണമെങ്കിൽ ഒരു ലേബലോടെ; ഒരു ബേസ്‌ലൈൻ ഒരിക്കലും എഡിറ്റ് ചെയ്യില്ല, പകരം പുതിയത് എടുക്കും.',
            'p2' => 'ഒരു **മാറ്റ അഭ്യർത്ഥന** സമ്മതിച്ച പദ്ധതി മാറ്റുന്നതിന് മുമ്പ് അതിന് അനുമതി ചോദിക്കുന്നു: എന്താണ് മാറ്റം, എന്തുകൊണ്ട്, അത് സമയത്തെ (ദിവസങ്ങൾ, + വൈകൽ), ചെലവിനെ (+ കൂടുതൽ, - ലാഭം), വ്യാപ്തിയെ എങ്ങനെ ബാധിക്കുന്നു. **Raise** അമർത്തുക. ഉന്നയിച്ചയാൾക്ക് അത് കാത്തിരിക്കുമ്പോൾ എഡിറ്റ് ചെയ്യാനോ പിൻവലിക്കാനോ കഴിയും. അത് **അംഗീകരിക്കുമ്പോൾ** ഒരു പുതിയ ബേസ്‌ലൈൻ എടുക്കും - മാറ്റിയ പദ്ധതി സമ്മതിച്ചതായി മാറും - സ്ഥിരസ്ഥിതിയായി, ലക്ഷ്യ പൂർത്തീകരണം അതിന്റെ ദിവസങ്ങൾ കൊണ്ട് നീങ്ങുകയും അതിന്റെ ചെലവ് അതിന്റെ പേരിലുള്ള ഒരു ബജറ്റ് ലൈൻ ആകുകയും ചെയ്യും. **നിരസിക്കുന്നത്** തീരുമാനം രേഖപ്പെടുത്തുകയും ഒന്നും മാറ്റാതിരിക്കുകയും ചെയ്യുന്നു. അഭ്യർത്ഥനകൾ ഒരിക്കലും ഇല്ലാതാക്കില്ല: പദ്ധതി എന്തുകൊണ്ട് നീങ്ങി എന്നതിന്റെ രേഖയാണ് അവ, ഓരോന്നും ചരിത്രത്തിലുണ്ട്. മറ്റൊരാൾ ഉന്നയിച്ച അഭ്യർത്ഥനയെക്കുറിച്ച് പ്രോജക്റ്റ് മാനേജരെ അറിയിക്കുന്നു, കാത്തിരിക്കുന്ന അഭ്യർത്ഥന Overview-ലും പോർട്ട്ഫോളിയോ കാർഡിലും കാണിക്കുന്നു.',
            'p3' => 'ഇത് നിങ്ങൾക്ക് എങ്ങനെ പ്രവർത്തിക്കണമെന്ന് Projects - Settings - General തീരുമാനിക്കുന്നു: ഒരു പ്രോജക്റ്റ് സജീവമാകുമ്പോൾ ബേസ്‌ലൈൻ **സ്വയം** എടുക്കണോ, അതോ അപ്പോഴും **ഒപ്പം** ഓരോ ഘട്ടം തുടങ്ങുമ്പോഴും (സ്ഥിരസ്ഥിതി), അതോ കൈകൊണ്ട് മാത്രമോ; മാറ്റ അഭ്യർത്ഥനകൾ **ആര് തീരുമാനിക്കുന്നു** - പ്രോജക്റ്റ് മാനേജർ അല്ലെങ്കിൽ Projects മാനേജ് ചെയ്യുന്ന ആർക്കും (സ്ഥിരസ്ഥിതി), പ്രോജക്റ്റ് ടീമിലെ ആർക്കും, അല്ലെങ്കിൽ Projects മാനേജ് ചെയ്യുന്നവർക്ക് മാത്രം; അഭ്യർത്ഥന ഉന്നയിച്ചയാൾക്കും **അത് തീരുമാനിക്കാമോ**; അനുമതി നൽകുമ്പോൾ **പദ്ധതിയും നീക്കണോ** അതോ പുതിയ ബേസ്‌ലൈൻ എടുക്കുക മാത്രം ചെയ്യണോ.',
        ],
        'announce' => [
            'nav' => 'തടസ്സം അറിയിക്കൽ',
            'title' => 'Service Status-ൽ തടസ്സം അറിയിക്കൽ',
            'intro' => '"Move day: ശനിയാഴ്ച ഫോണുകൾ പ്രവർത്തിക്കില്ല" - അത് സംഭവിക്കുന്നതിന് മുമ്പ് എല്ലാവരെയും അറിയിക്കുന്നു.',
            'p1' => 'Service Status തുറക്കാൻ കഴിയുന്നവർക്കായി Connections ടാബിൽ ഒരു **Service Status** പാനൽ ഉണ്ട്. **Announce** അമർത്തി ഒരു തലക്കെട്ട്, എപ്പോൾ തുടങ്ങുന്നു, എപ്പോൾ അവസാനിക്കുന്നു, ആളുകൾ അറിയേണ്ടത്, ബാധിക്കുന്ന സേവനങ്ങൾ എന്നിവ നൽകുക (മറ്റൊരു ആഘാതം തിരഞ്ഞെടുത്തില്ലെങ്കിൽ Maintenance). സ്ഥിരസ്ഥിതിയായി അത് **ആസൂത്രിത അറ്റകുറ്റപ്പണി** ആകുന്നു: Service Status-ൽ അത് ഉടൻ Upcoming ആയി കാണിക്കും, തുടങ്ങുമ്പോൾ ആ സേവനങ്ങളിൽ ഒരു ഇൻസിഡന്റ് ആകും, അവസാനിക്കുമ്പോൾ പരിഹരിക്കപ്പെടും. തുടങ്ങുന്നതിന് മുമ്പ് ക്രോസ് ഉപയോഗിച്ച് പിൻവലിക്കാം. പ്രോജക്റ്റ് അറിയിച്ചതെല്ലാം പാനൽ പട്ടികപ്പെടുത്തുന്നു, അറിയിക്കലും പിൻവലിക്കലും പ്രോജക്റ്റിന്റെ ചരിത്രത്തിൽ ചേരും.',
            'p2' => '**Projects - Settings - General - Announce disruption on Service Status** ആണ് Announce എന്ത് ചെയ്യണമെന്ന് തീരുമാനിക്കുന്നത്: ആസൂത്രിത അറ്റകുറ്റപ്പണിയായി (സ്ഥിരസ്ഥിതി), ഉടൻ ഒരു ഇൻസിഡന്റായി, അല്ലെങ്കിൽ ഒട്ടും വേണ്ട. പ്രോജക്റ്റ് ഇല്ലാതാക്കിയാലും അത് അറിയിച്ചത് Service Status-ൽ നിലനിൽക്കും: അത് യഥാർത്ഥ സേവനങ്ങളിലെ യഥാർത്ഥ ജോലിയാണ്.',
        ],
        'reports' => [
            'nav' => 'ബ്രീഫിംഗുകളും റിപ്പോർട്ടുകളും',
            'title' => 'AI പ്രോജക്റ്റ് മാനേജർ: ബ്രീഫിംഗുകളും റിപ്പോർട്ടുകളും',
            'intro' => 'ഈ ആഴ്ച നിങ്ങളുടെ ശ്രദ്ധ വേണ്ടതിനെക്കുറിച്ചുള്ള ഒരു ബ്രീഫിംഗ്, പരിശോധിക്കാനായി നിങ്ങൾക്ക് തയ്യാറാക്കിയ സ്റ്റാറ്റസ് റിപ്പോർട്ടുകൾ.',
            'p1' => '**Projects - Settings - AI**-ൽ ഒരു AI ദാതാവിനെ സജ്ജമാക്കിയാൽ, പ്രോജക്റ്റിന്റെ Overview-ൽ ഒരു **ബ്രീഫിംഗ്** പാനൽ ഉണ്ടാകും. **Brief me** അമർത്തുക, AI പ്രോജക്റ്റ് വായിക്കുന്നു - തീയതികൾ, ആരോഗ്യം, സഹിഷ്ണുതകൾ, ഘട്ടങ്ങൾ, കാലാവധി കഴിഞ്ഞതും വരാനുള്ളതുമായ ടാസ്കുകൾ, റിസ്കുകളും ഇഷ്യൂകളും, ബജറ്റ്, കഴിഞ്ഞ ആഴ്ചയിലെ മാറ്റങ്ങൾ, 3.3.0 മുതൽ മുൻഗണന, മൈൽസ്റ്റോണുകൾ, എസ്റ്റിമേറ്റുകൾ, തീരുമാനങ്ങൾ, മാറ്റ അഭ്യർത്ഥനകൾ, എർണ്ഡ് വാല്യു, ബെനിഫിറ്റുകൾ, മറ്റുള്ളവയ്ക്കായി കാത്തിരിക്കുന്ന ടാസ്കുകളും ക്രിട്ടിക്കൽ പാതയും, ഇനിയും തുറന്നിരിക്കുന്ന ഗേറ്റ് ചെക്ക്‌ലിസ്റ്റ് ഇനങ്ങൾ, സ്റ്റേക്ക്ഹോൾഡർ മാപ്പ് എന്നിവയും - ശ്രദ്ധ വേണ്ടതിനെക്കുറിച്ച് ഏറ്റവും പ്രധാനപ്പെട്ടത് ആദ്യം വരുന്ന നാല് മുതൽ ഏഴ് വരെ ഹ്രസ്വ പോയിന്റുകൾ എഴുതുന്നു. ഏറ്റവും പുതിയ ബ്രീഫിംഗ് എല്ലാവർക്കുമായി പേജിൽ നിലനിൽക്കും; ഓരോന്നും ദാതാവിലേക്കുള്ള ഒരു കോൾ ആയതിനാൽ പുതിയത് പരമാവധി ഓരോ 10 മിനിറ്റിലും മാത്രമേ തയ്യാറാക്കൂ.',
            'p2' => '**Reports** ടാബിൽ പ്രോജക്റ്റിന്റെ ഹൈലൈറ്റ്, എക്സെപ്ഷൻ, ചെക്ക്പോയിന്റ്, ക്ലോഷർ റിപ്പോർട്ടുകൾ ഉണ്ട്. തരവും കാലയളവും തിരഞ്ഞെടുത്ത് AI ഒന്ന് എഴുതാൻ **Draft** അമർത്തുക, അല്ലെങ്കിൽ സ്വന്തമായി തുടങ്ങാൻ **Write** അമർത്തുക. പ്രോജക്റ്റ് മാറ്റാൻ അനുവാദമുള്ള ആർക്കും ഡ്രാഫ്റ്റ് തയ്യാറാക്കാനും എഡിറ്റ് ചെയ്യാനും ഇല്ലാതാക്കാനും കഴിയും. **അനുമതി നൽകൽ** പ്രോജക്റ്റ് മാനേജർക്കും, പ്രോജക്റ്റ് ഉണ്ടാക്കിയ ആൾക്കും, Projects മാനേജ് ചെയ്യുന്നവർക്കുമുള്ളതാണ് - അനുമതി ലഭിച്ച റിപ്പോർട്ട് അന്തിമമാണ്, എഡിറ്റ് ചെയ്യാൻ കഴിയില്ല, ബോർഡ് വായിക്കുന്നത് അതാണ്. ഓരോ റിപ്പോർട്ടും AI തയ്യാറാക്കിയതാണോ എന്നും അതിനുശേഷം ഒരു വ്യക്തി മാറ്റിയിട്ടുണ്ടോ എന്നും കാണിക്കുന്നു. **Copy** അതിനെ ക്ലിപ്ബോർഡിൽ ഇടുന്നു, ഒരു ഇമെയിലിലോ പ്രമാണത്തിലോ ഒട്ടിക്കാൻ.',
            'p3' => 'ചോദിക്കുന്ന വ്യക്തിക്ക് കാണാൻ കഴിയുന്നത് മാത്രമേ AI കാണൂ: ആ മൊഡ്യൂളുകൾ ഇല്ലാത്തവർക്ക് ടിക്കറ്റുകൾ, മാറ്റങ്ങൾ, Service Status എന്നിവ ഒഴിവാക്കും. പ്രോജക്റ്റിലുള്ളത് മാത്രം പറയാനും എന്തെങ്കിലും അറിയില്ലെങ്കിൽ അത് പറയാനും അതിനോട് നിർദ്ദേശിച്ചിട്ടുണ്ട് - എന്നാലും അത് തെറ്റാകാം, അതിനാൽ അനുമതി നൽകുന്നതിന് മുമ്പ് ഡ്രാഫ്റ്റ് വായിക്കുക. നിങ്ങൾ FreeITSM ഉപയോഗിക്കുന്ന ഭാഷയിലാണ് അത് എഴുതുന്നത്. ആളുകൾ പ്രോജക്റ്റിൽ ടൈപ്പ് ചെയ്ത ടെക്സ്റ്റ് ഡാറ്റയായാണ് കൈമാറുന്നത്, ഒരിക്കലും നിർദ്ദേശങ്ങളായിട്ടല്ല.',
            'p4' => '**റിപ്പോർട്ട് സ്വയം തയ്യാറാക്കുക** (Reports ടാബിൽ): പ്രോജക്റ്റ് സജീവമായിരിക്കുമ്പോൾ ഓരോ ആഴ്ചയും, രണ്ടാഴ്ചയിലൊരിക്കൽ, അല്ലെങ്കിൽ മാസംതോറും, കാലയളവിന്റെ തുടക്കത്തിൽ ഒരു ഹൈലൈറ്റ്, ചെക്ക്പോയിന്റ് അല്ലെങ്കിൽ എക്സെപ്ഷൻ റിപ്പോർട്ട് തയ്യാറാക്കുന്നു - AI സജ്ജമാക്കിയിട്ടുണ്ടെങ്കിൽ AI, അല്ലെങ്കിൽ അത് എഴുതാനുള്ള വസ്തുതകൾ അടങ്ങിയത് - പ്രോജക്റ്റ് മാനേജരെ അറിയിക്കുകയും ചെയ്യുന്നു. ഇത് പ്രോജക്റ്റ് മാനേജരുടെ ആക്സസ് ഉപയോഗിച്ചാണ് എഴുതുന്നത്, അതിനാൽ അവർക്ക് കാണാൻ കഴിയുന്നത് മാത്രമേ അതിലുണ്ടാകൂ. ഇത് ഒരിക്കലും സ്വയം അനുമതി നേടുന്നില്ല. അനുമതി ലഭിച്ച റിപ്പോർട്ടിലെ **Send** അത് നിങ്ങൾ ടിക്ക് ചെയ്യുന്ന പ്രോജക്റ്റ് അംഗങ്ങൾക്കും മറ്റ് വിലാസങ്ങൾക്കും, മുകളിൽ ഒരു ഓപ്ഷണൽ കുറിപ്പോടെ ഇമെയിൽ ചെയ്യുന്നു; റിപ്പോർട്ട് ആർക്ക്, എപ്പോൾ പോയി എന്ന് കാണിക്കുന്നു.',
        ],
        'assistant' => [
            'nav' => 'AI യോട് ചോദിക്കുക',
            'title' => 'AI യോട് ചോദിക്കുക - പ്രോജക്റ്റ് അസിസ്റ്റന്റ്',
            'intro' => 'ഒരു പ്രോജക്റ്റിനെക്കുറിച്ച് അത് വായിക്കാനും മാറ്റങ്ങൾ നിർദ്ദേശിക്കാനും കഴിയുന്ന ഒരു AI പ്രോജക്റ്റ് മാനേജരുമായുള്ള സംഭാഷണം.',
            'p1' => 'ഒരു പ്രോജക്റ്റിൽ, **AI യോട് ചോദിക്കുക** (മുകളിൽ വലത്) അസിസ്റ്റന്റിനെ സ്ലൈഡ് ചെയ്ത് കൊണ്ടുവരുന്നു. നിങ്ങൾക്ക് വായിക്കാൻ കഴിയുന്ന പോലെ തന്നെ അത് പ്രോജക്റ്റ് വായിക്കുന്നു - നിങ്ങൾക്ക് സ്വയം തുറക്കാൻ കഴിയാത്തതൊന്നും വായിക്കില്ല - ലളിതമായ വാക്കുകളിൽ ഉത്തരം നൽകുന്നു, നിങ്ങൾ ഒരിക്കലും പ്രോജക്റ്റ് നടത്തിയിട്ടില്ലെങ്കിലും PRINCE2 ഹൃദിസ്ഥമാണെങ്കിലും. Projects - Settings - AI-ൽ ഒരു AI ദാതാവിനെ സജ്ജമാക്കിയാൽ മാത്രം.',
            'p2' => 'പ്രോജക്റ്റ് എത്രത്തോളം സജ്ജമാക്കിയിട്ടുണ്ടെന്ന് അത് മനസ്സിലാക്കുന്നു. ഒരു പേരല്ലാതെ കാര്യമായൊന്നുമില്ലാത്ത പ്രോജക്റ്റിന് ഒരു **കോച്ച്** ലഭിക്കും: ഇത് എന്തിനെക്കുറിച്ചാണ്, പൂർത്തിയായാൽ എങ്ങനെയിരിക്കും, ഏകദേശം എപ്പോൾ, ആരൊക്കെ ഉൾപ്പെടുന്നു - എന്നിട്ട് ഒരു നിർദ്ദിഷ്ട സജ്ജീകരണം: ലക്ഷ്യം, തീയതികൾ, നടത്തുന്ന രീതി, ഘട്ടങ്ങൾ, തുടക്ക ടാസ്കുകൾ, മൈൽസ്റ്റോണുകൾ, സാധ്യതയുള്ള റിസ്കുകൾ. നടന്നുകൊണ്ടിരിക്കുന്ന പ്രോജക്റ്റിന് **കാര്യങ്ങൾ നിയന്ത്രണത്തിൽ വയ്ക്കാൻ** സഹായം ലഭിക്കും: എന്താണ് കാലാവധി കഴിഞ്ഞത്, ഉയർന്ന റിസ്കുകൾ, നഷ്ടപ്പെട്ട മൈൽസ്റ്റോണുകൾ, കാത്തിരിക്കുന്ന മാറ്റ അഭ്യർത്ഥനകൾ. സംഭാഷണത്തിന് താഴെയുള്ള ബട്ടണുകൾ തുടങ്ങാനുള്ള ഒരു ചോദ്യം നിർദ്ദേശിക്കുന്നു.',
            'p3' => '**ഇത് ഒരിക്കലും സ്വയം പ്രോജക്റ്റ് മാറ്റില്ല.** നിർദ്ദേശിക്കുന്ന മാറ്റങ്ങൾ ഒരു കാർഡായി വരുന്നു - ഓരോന്നിനും ഒരു ബോക്സ്, എല്ലാം ടിക്ക് ചെയ്തത് - **Apply**, **Dismiss** എന്നിവയോടെ. നിങ്ങൾ സ്ക്രീനുകളിൽ ചെയ്തിരുന്നെങ്കിൽ എന്ന പോലെ തന്നെ, നിങ്ങളുടെ അനുമതികളോടെ, Apply ടിക്ക് ചെയ്തവ ചെയ്യുന്നു, അവ ചരിത്രത്തിൽ നിങ്ങളുടേതായി കാണിക്കും. പ്രോജക്റ്റ് മാറ്റാൻ നിങ്ങൾക്ക് അനുവാദമില്ലെങ്കിൽ, അത് പകരം ഉപദേശം നൽകുന്നു.',
            'p4' => '**ഇത് ഓർക്കുന്നു.** ഒരു പ്രോജക്റ്റിലെ നിങ്ങളുടെ സംഭാഷണം സൂക്ഷിക്കുന്നു, പഴയ ഭാഗങ്ങൾ ഒരു ചെറിയ ഓർമ്മയിലേക്ക് ചുരുക്കുന്നു, അതിനാൽ നിങ്ങൾ നിർത്തിയിടത്തുനിന്ന് തുടരാം; കുറച്ചുകാലം മാറിനിന്നാൽ, അതിനുശേഷം എന്താണ് മാറിയത് എന്നതോടെ അത് തുറക്കുന്നു. **Restart** അത് മറക്കുന്നു. Projects - Settings - General - *AI assistant\'s memory* ഓരോരുത്തർക്കും ഓരോന്നിന് പകരം മുഴുവൻ പ്രോജക്റ്റ് ടീമും പങ്കിടുന്ന ഒരൊറ്റ സംഭാഷണമാക്കുന്നു.',
        ],
        'companies' => [
            'nav' => 'കമ്പനികൾ',
            'title' => 'പ്രോജക്റ്റുകളും കമ്പനികളും',
            'intro' => 'ഓരോ പ്രോജക്റ്റും ഒരു കമ്പനിയുടേതാണ്.',
            'p1' => 'ഒന്നിലധികം കമ്പനികളുള്ള ഇൻസ്റ്റലേഷനിൽ, ഒരു പ്രോജക്റ്റ് അത് ഉണ്ടാക്കിയ കമ്പനിയുടേതാണ് (അല്ലെങ്കിൽ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നതിന്റെ), അതിന്റെ ടാസ്കുകളും അവിടെത്തന്നെ. നിങ്ങൾക്ക് കാണാൻ കഴിയുന്ന കമ്പനികളുടെ പ്രോജക്റ്റുകൾ മാത്രമേ കാണൂ, All companies വ്യൂ അവയെ ഒരുമിച്ച് കാണിക്കുന്നു. മറ്റൊരു കമ്പനിയുടെ ടാസ്ക് ഒരു പ്രോജക്റ്റിൽ ഇടാൻ കഴിയില്ല.',
        ],
        'settings' => [
            'nav' => 'ക്രമീകരണങ്ങൾ',
            'title' => 'ക്രമീകരണങ്ങളും അനുമതികളും',
            'intro' => 'ആർക്കൊക്കെ പ്രോജക്റ്റുകൾ ഉണ്ടാക്കാനും മാറ്റാനും ഇല്ലാതാക്കാനും കഴിയും, മൊഡ്യൂൾ ഉപയോഗിക്കുന്ന വാക്കുകളും പരിധികളും.',
            'p1' => '**Projects - Settings**-ന് ഏഴ് ടാബുകളുണ്ട്, ഓരോന്നിനും **System - Roles**-ൽ നൽകുന്ന സ്വന്തം അനുമതി വേണം; Manage Projects ഏഴിനെയും ഉൾക്കൊള്ളുന്നു. അവയിൽ ഒന്നുമില്ലാത്ത ഒരാൾക്ക് ക്രമീകരിക്കാൻ ഒന്നുമില്ല എന്ന് പറയുന്ന ഒരു പേജ് കാണാം.',
            'general_d' => 'നിങ്ങൾ മറ്റൊന്ന് തിരഞ്ഞെടുക്കുന്നില്ലെങ്കിൽ പുതിയ പ്രോജക്റ്റ് നടത്തുന്ന രീതി, ആർക്കൊക്കെ പ്രോജക്റ്റുകൾ ഉണ്ടാക്കാം, ആർക്കൊക്കെ ഒന്ന് മാറ്റാം, ഏത് തീയതികൾ Calendar-ൽ പോകും, Service Status-ൽ തടസ്സം എങ്ങനെ അറിയിക്കുന്നു. കൂടാതെ മുൻഗണനാ വാക്കുകൾ, പോർട്ട്ഫോളിയോയുടെ തുടക്ക ക്രമം, ബേൺ-അപ്പ് എന്ത് കണക്കാക്കുന്നു, മാറ്റ നിയന്ത്രണം (സ്വയമേവയുള്ള ബേസ്‌ലൈനുകൾ, ആര് തീരുമാനിക്കുന്നു, സ്വന്തം അഭ്യർത്ഥന തീരുമാനിക്കൽ, അനുമതി നൽകുന്നത് എന്ത് ചെയ്യുന്നു), Overview-ലെ ടൂൾബോക്സ് (ഓൺ), AI അസിസ്റ്റന്റിന്റെ ഓർമ്മ (ഓരോരുത്തർക്കും സ്വന്തം), കോൺട്രാക്ടർമാർക്ക് ഇമെയിൽ അയയ്ക്കണോ (ഓഫ്), കാലാവധി കഴിഞ്ഞ ടാസ്ക് ഡൈജസ്റ്റ് (ആഴ്ചതോറും), നഡ്ജുകൾ (3 ദിവസത്തിന് ശേഷം), ഒരു പുതിയ പ്രോജക്റ്റ് ആർക്ക് കാണാം (Projects ഉള്ള എല്ലാവർക്കും), തുറന്ന ഗേറ്റ് ചെക്ക്‌ലിസ്റ്റ് ഇനം ഒരു ഗോ തടയുമോ (തടയും), ബെനിഫിറ്റുകൾ എത്ര തവണ അവലോകനം ചെയ്യുന്നു (ഓരോ 3 മാസത്തിലും), ആരെ ഓർമ്മിപ്പിക്കുന്നു, ഏത് നിർദ്ദേശങ്ങൾക്ക് അനുമതി വേണം, ആര് അനുമതി നൽകുന്നു, അനുമതി നൽകുന്നത് എന്ത് ചെയ്യുന്നു എന്നിവയും.',
            'health_d' => 'ഒരു സജീവ പ്രോജക്റ്റ് എപ്പോൾ മഞ്ഞയോ ചുവപ്പോ ആകുന്നു: ലക്ഷ്യം എത്ര അടുത്താണ്, അപ്പോഴേക്കും എത്ര പൂർത്തിയാക്കണം, എത്ര കാലാവധി കഴിഞ്ഞ ജോലി അതിനെ ചുവപ്പാക്കുന്നു, എത്ര പുതിയ ലിങ്ക് ചെയ്ത ടിക്കറ്റുകൾ അതിനെ മഞ്ഞയാക്കുന്നു; നഷ്ടപ്പെട്ട മൈൽസ്റ്റോൺ, അല്ലെങ്കിൽ തീയതി കഴിഞ്ഞ ഡിപൻഡൻസി അല്ലെങ്കിൽ തീരുമാനം എന്ത് ചെയ്യുന്നു (സ്ഥിരസ്ഥിതിയായി മഞ്ഞ); Capacity പേജിലെ ആഴ്ചയിലെ മണിക്കൂറുകൾ, സ്ട്രെച്ച്ഡ് ലെവൽ, ഒന്നിലധികം പ്രോജക്റ്റുകൾ, പ്രവൃത്തി ദിനങ്ങൾ, റോട്ട ഷിഫ്റ്റുകൾ കണക്കാക്കുമോ എന്നിവ.',
            'roles_d' => 'പ്രോജക്റ്റിന്റെ People ടാബിൽ നൽകുന്ന റോളുകൾ. ക്രമം മാറ്റാൻ വലിച്ചിടുക; ഒരു റോൾ നൽകുന്നത് നിർത്താൻ Offered on projects ടിക്ക് മാറ്റുക; ഒന്ന് ഇല്ലാതാക്കിയാൽ അതിന്റെ ഉടമകൾ റോൾ ഇല്ലാതെ അവരുടെ പ്രോജക്റ്റുകളിൽ തുടരും.',
            'raid_d' => 'സാധ്യതാ സ്കെയിലിന്റെയും ആഘാത സ്കെയിലിന്റെയും പടികൾക്കുള്ള അഞ്ച് വാക്കുകൾ, ഏറ്റവും താഴ്ന്നത് ആദ്യം.',
            'ai_d' => 'ബ്രീഫിംഗുകളും തയ്യാറാക്കിയ റിപ്പോർട്ടുകളും ഉപയോഗിക്കുന്ന AI ദാതാവ്, മോഡൽ, കീ. കീ നിങ്ങളുടെ സ്ഥാപനത്തിന്റെ പണം ചെലവഴിക്കുന്നു, അതിനാൽ ഇതിന് സ്വന്തം അനുമതിയുണ്ട്.',
            'budget_d' => 'പുതിയ പ്രോജക്റ്റുകൾക്കുള്ള കറൻസി, ഒരു പ്രോജക്റ്റിന് സ്വന്തമായി തിരഞ്ഞെടുക്കാമോ, രേഖപ്പെടുത്തിയ സമയത്തിന് എങ്ങനെ വില നിശ്ചയിക്കുന്നു, മണിക്കൂർ നിരക്കുകൾ - സ്ഥിരസ്ഥിതിയും ഓരോ അനലിസ്റ്റിന്റെയും - ഓരോന്നും ഒരു തീയതി മുതൽ. കൂടാതെ അധികച്ചെലവ് അനുവദനീയം ചെലവായതിനെ (സ്ഥിരസ്ഥിതി) അളക്കുമോ അതോ ഫോർകാസ്റ്റിനെയോ, തുറന്ന ടാസ്കുകളിൽ ഇനിയും എസ്റ്റിമേറ്റ് ചെയ്ത മണിക്കൂറുകൾ ഫോർകാസ്റ്റിൽ കണക്കാക്കുമോ (കണക്കാക്കും) എന്നിവയും.',
            'templates_d' => 'പുതിയ പ്രോജക്റ്റുകൾക്ക് നൽകുന്ന ടെംപ്ലേറ്റുകൾ: ബിൽറ്റ്-ഇൻ ഒന്ന് മറയ്ക്കുക, ഒരു പ്രോജക്റ്റിൽ നിന്ന് സേവ് ചെയ്തവ പേര് മാറ്റുക, ഓഫാക്കുക അല്ലെങ്കിൽ ഇല്ലാതാക്കുക. ഇതേ അനുമതി ഒരു പ്രോജക്റ്റിനെ ടെംപ്ലേറ്റായി സേവ് ചെയ്യാനും ഒരാളെ അനുവദിക്കുന്നു.',
            'p2' => '**ആർക്ക് പ്രോജക്റ്റുകൾ ഉണ്ടാക്കാം** എന്നത് Projects തുറക്കാൻ കഴിയുന്ന ആർക്കും (സ്ഥിരസ്ഥിതി) അല്ലെങ്കിൽ Projects മാനേജ് ചെയ്യുന്നവർക്ക് മാത്രം എന്നതാണ്. **ആർക്ക് ഒരു പ്രോജക്റ്റ് മാറ്റാം** എന്നത് അതിന്റെ ടീമിന് (സ്ഥിരസ്ഥിതി) അല്ലെങ്കിൽ Projects തുറക്കാൻ കഴിയുന്ന ആർക്കും എന്നതാണ്. ഒരു പ്രോജക്റ്റിന്റെ ടീം എന്നത് അതിന്റെ പ്രോജക്റ്റ് മാനേജർ, അത് ഉണ്ടാക്കിയ ആൾ, അംഗങ്ങൾ - അംഗമായ ഒരു ടീമിലെ അനലിസ്റ്റുകൾ ഉൾപ്പെടെ - ആണ്. Projects മാനേജ് ചെയ്യുന്നവർക്കും അഡ്മിനിസ്ട്രേറ്റർമാർക്കും എപ്പോഴും ഏത് പ്രോജക്റ്റും മാറ്റാം.',
            'p3' => 'ഒരു പ്രോജക്റ്റ് **ഇല്ലാതാക്കുന്നത്**, ക്രമീകരണങ്ങൾ എന്ത് പറഞ്ഞാലും, അതിന്റെ പ്രോജക്റ്റ് മാനേജർക്കും, അത് ഉണ്ടാക്കിയ ആൾക്കും, Projects മാനേജ് ചെയ്യുന്നവർക്കും മാത്രമായി എപ്പോഴും പരിമിതപ്പെടുത്തിയിരിക്കുന്നു. ഒരു പ്രോജക്റ്റ് മാറ്റാൻ നിങ്ങൾക്ക് അനുവാദമില്ലാത്തപ്പോൾ, അതിന്റെ പേജ് മാറ്റം വരുത്തുന്ന ബട്ടണുകൾ മറയ്ക്കുന്നു, സെർവർ എന്തായാലും മാറ്റം നിരസിക്കുന്നു.',
        ],
        'api' => [
            'nav' => 'API',
            'title' => 'API വഴി പ്രോജക്റ്റുകൾ',
            'intro' => 'സ്ക്രിപ്റ്റുകൾക്കും മറ്റ് സിസ്റ്റങ്ങൾക്കും AI അസിസ്റ്റന്റുകൾക്കും.',
            'p1' => 'പ്രോജക്റ്റുകൾ REST API വഴി വായിക്കാനും മാറ്റാനും കഴിയും, MCP സെർവർ വഴി ഒരു AI അസിസ്റ്റന്റിന് വായിക്കാനും. രണ്ടും **System - API**-ൽ സജ്ജമാക്കുന്നു, ഒരു API കീ അതിന്റെ അനലിസ്റ്റിന് കാണാൻ കഴിയുന്ന കമ്പനികളിൽ മാത്രമേ എത്തൂ.',
            'p2' => '**War Room**-ൽ, Warbot പ്രോജക്റ്റുകളെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾക്കും ഉത്തരം നൽകുന്നു - "ഏത് പ്രോജക്റ്റുകളാണ് ട്രാക്കിന് പുറത്ത്?", "ഏതെങ്കിലും പ്രോജക്റ്റ് ഈ ആഴ്ച വലിയ എന്തെങ്കിലും ചെയ്യുന്നുണ്ടോ?" - അല്ലെങ്കിൽ **/projects**, **/project**, **/dates** ഉപയോഗിക്കുക. ഇത് Projects തുറക്കാൻ കഴിയുന്നവർക്ക് മാത്രമേ ലഭിക്കൂ, അവർക്ക് കാണാൻ കഴിയുന്ന പ്രോജക്റ്റുകളെക്കുറിച്ച് ഉത്തരം നൽകുന്നു, പണത്തെക്കുറിച്ച് ഒരിക്കലും പറയുന്നില്ല: ചാനലിലെ എല്ലാവരും അതിന്റെ മറുപടികൾ വായിക്കുന്നു.',
        ],
    ],
